begin;
    with j as (select * from jsonb_to_recordset($law7v021$[{"code_id":"KONST_RF","article_number":"14","version_date":"1993-12-12","article_text":"1.Российская Федерация — светское государство. Никакая религия не может устанавливаться в качестве государственной или обязательной.\n\n2.Религиозные объединения отделены от государства и равны перед законом.","article_title":"Статья 14","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d1548e1bc2830f017864579caf5b8b3ea8d337e1bcb37a3040e197e5cb129297"},{"code_id":"KONST_RF","article_number":"15","version_date":"1993-12-12","article_text":"1.Конституция Российской Федерации имеет высшую юридическую силу, прямое действие и применяется на всей территории Российской Федерации. Законы и иные правовые акты, принимаемые в Российской Федерации, не должны противоречить Конституции Российской Федерации.\n\n2.Органы государственной власти, органы местного самоуправления, должностные лица, граждане и их объединения обязаны соблюдать Конституцию Российской Федерации и законы.\n\n3.Законы подлежат официальному опубликованию. Неопубликованные законы не применяются. Любые нормативные правовые акты, затрагивающие права, свободы и обязанности человека и гражданина, не могут применяться, если они не опубликованы официально для всеобщего сведения.\n\n4.Общепризнанные принципы и нормы международного права и международные договоры Российской Федерации являются составной частью ее правовой системы. Если международным договором Российской Федерации установлены иные правила, чем предусмотренные законом, то применяются правила международного договора.","article_title":"Статья 15","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"958d8524aa72f9fa643c8763768210fc8ac5d89f3be52d39dff3a34adfccacf5"},{"code_id":"KONST_RF","article_number":"16","version_date":"1993-12-12","article_text":"1.Положения настоящей главы Конституции составляют основы конституционного строя Российской Федерации и не могут быть изменены иначе как в порядке, установленном настоящей Конституцией.\n\n2.Никакие другие положения настоящей Конституции не могут противоречить основам конституционного строя Российской Федерации.","article_title":"Статья 16","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1171e46737e4585b9a1bfc5a36a29f80d4c64dce780c78d505e47c152747193f"},{"code_id":"KONST_RF","article_number":"17","version_date":"1993-12-12","article_text":"1.В Российской Федерации признаются и гарантируются права и свободы человека и гражданина согласно общепризнанным принципам и нормам международного права и в соответствии с настоящей Конституцией.\n\n2.Основные права и свободы человека неотчуждаемы и принадлежат каждому от рождения.\n\n3.Осуществление прав и свобод человека и гражданина не должно нарушать права и свободы других лиц.","article_title":"Статья 17","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e59a368abf382b5ca605ad000f03a961e4b7ea9bb7f2e3b4c2f9e5f1cfdebaad"},{"code_id":"KONST_RF","article_number":"18","version_date":"1993-12-12","article_text":"Права и свободы человека и гражданина являются непосредственно действующими. Они определяют смысл, содержание и применение законов, деятельность законодательной и исполнительной власти, местного самоуправления и обеспечиваются правосудием.","article_title":"Статья 18","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a7dce7de628092a1a8514518c0ecffde4b41daf7ac11d6d68aa1e59efb19817"},{"code_id":"KONST_RF","article_number":"19","version_date":"1993-12-12","article_text":"1.Все равны перед законом и судом.\n\n2.Государство гарантирует равенство прав и свобод человека и гражданина независимо от пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям, а также других обстоятельств. Запрещаются любые формы ограничения прав граждан по признакам социальной, расовой, национальной, языковой или религиозной принадлежности.\n\n3.Мужчина и женщина имеют равные права и свободы и равные возможности для их реализации.","article_title":"Статья 19","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"29e22423d027492d8783086b6044c208ca9fd01a319e21adf96e9d89988ecd76"},{"code_id":"KONST_RF","article_number":"2","version_date":"1993-12-12","article_text":"Человек, его права и свободы являются высшей ценностью. Признание, соблюдение и защита прав и свобод человека и гражданина — обязанность государства.","article_title":"Статья 2","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5415fe27b68d848904b384bb9409ce2a7d5607f8c7597deafb5adaaac370819f"},{"code_id":"KONST_RF","article_number":"20","version_date":"1993-12-12","article_text":"1.Каждый имеет право на жизнь.\n\n2.Смертная казнь впредь до ее отмены может устанавливаться федеральным законом в качестве исключительной меры наказания за особо тяжкие преступления против жизни при предоставлении обвиняемому права на рассмотрение его дела судом с участием присяжных заседателей.","article_title":"Статья 20","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fd881dd30ea2d850e0770ec8df37cde6ff9f8aaca071e5e7d7bd27dc72eba36c"},{"code_id":"KONST_RF","article_number":"21","version_date":"1993-12-12","article_text":"1.Достоинство личности охраняется государством. Ничто не может быть основанием для его умаления.\n\n2.Никто не должен подвергаться пыткам, насилию, другому жестокому или унижающему человеческое достоинство обращению или наказанию. Никто не может быть без добровольного согласия подвергнут медицинским, научным или иным опытам.","article_title":"Статья 21","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"11191b06dd976d06a0d596284b77ec5b42725ca257bd0ca6c70c0c8a133a46b7"},{"code_id":"KONST_RF","article_number":"22","version_date":"1993-12-12","article_text":"1.Каждый имеет право на свободу и личную неприкосновенность.\n\n2.Арест, заключение под стражу и содержание под стражей допускаются только по судебному решению. До судебного решения лицо не может быть подвергнуто задержанию на срок более 48 часов.","article_title":"Статья 22","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"628dbfaf38053db3a09de9b0b765e5aeb1fa4a32ae7f1c37851e7426d2e4c89c"},{"code_id":"KONST_RF","article_number":"23","version_date":"1993-12-12","article_text":"1.Каждый имеет право на неприкосновенность частной жизни, личную и семейную тайну, защиту своей чести и доброго имени.\n\n2.Каждый имеет право на тайну переписки, телефонных переговоров, почтовых, телеграфных и иных сообщений. Ограничение этого права допускается только на основании судебного решения.","article_title":"Статья 23","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"515a42e3843c0693b545ae74568fc8f15d084b25ec2365be57b5e3058df2d49e"},{"code_id":"KONST_RF","article_number":"24","version_date":"1993-12-12","article_text":"1.Сбор, хранение, использование и распространение информации о частной жизни лица без его согласия не допускаются.\n\n2.Органы государственной власти и органы местного самоуправления, их должностные лица обязаны обеспечить каждому возможность ознакомления с документами и материалами, непосредственно затрагивающими его права и свободы, если иное не предусмотрено законом.","article_title":"Статья 24","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6389a41eae751d6f71be0257ce1e09f9065c6ea0527f3e4d77434040bc44f533"},{"code_id":"KONST_RF","article_number":"25","version_date":"1993-12-12","article_text":"Жилище неприкосновенно. Никто не вправе проникать в жилище против воли проживающих в нем лиц иначе как в случаях, установленных федеральным законом, или на основании судебного решения.","article_title":"Статья 25","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c14b91b512a98c77c4b8c377aecbb7a52e8565e7da4acb0205a7199bf3f66753"},{"code_id":"KONST_RF","article_number":"26","version_date":"1993-12-12","article_text":"1.Каждый вправе определять и указывать свою национальную принадлежность. Никто не может быть принужден к определению и указанию своей национальной принадлежности.\n\n2.Каждый имеет право на пользование родным языком, на свободный выбор языка общения, воспитания, обучения и творчества.","article_title":"Статья 26","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"160232a4eee30d05c38eefded4bd96498c8265afa7076992edccd602baa09d95"},{"code_id":"KONST_RF","article_number":"27","version_date":"1993-12-12","article_text":"1.Каждый, кто законно находится на территории Российской Федерации, имеет право свободно передвигаться, выбирать место пребывания и жительства.\n\n2.Каждый может свободно выезжать за пределы Российской Федерации. Гражданин Российской Федерации имеет право беспрепятственно возвращаться в Российскую Федерацию.","article_title":"Статья 27","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1286311c35bfca5ce9c11205fc394dc78de58a3ece1af8361584cddba95134b"},{"code_id":"KONST_RF","article_number":"28","version_date":"1993-12-12","article_text":"Каждому гарантируется свобода совести, свобода вероисповедания, включая право исповедовать индивидуально или совместно с другими любую религию или не исповедовать никакой, свободно выбирать, иметь и распространять религиозные и иные убеждения и действовать в соответствии с ними.","article_title":"Статья 28","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"070fc9943614b3e8d5e898dc2b082701359c77e1ffdd806229a18813d69de895"},{"code_id":"KONST_RF","article_number":"29","version_date":"1993-12-12","article_text":"1.Каждому гарантируется свобода мысли и слова.\n\n2.Не допускаются пропаганда или агитация, возбуждающие социальную, расовую, национальную или религиозную ненависть и вражду. Запрещается пропаганда социального, расового, национального, религиозного или языкового превосходства.\n\n3.Никто не может быть принужден к выражению своих мнений и убеждений или отказу от них.\n\n4.Каждый имеет право свободно искать, получать, передавать, производить и распространять информацию любым законным способом. Перечень сведений, составляющих государственную тайну, определяется федеральным законом.\n\n5.Гарантируется свобода массовой информации. Цензура запрещается.","article_title":"Статья 29","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"97ad8805f147b36231feb706f5dbbc585c10fee97a8218f3abccc321965a2b30"},{"code_id":"KONST_RF","article_number":"3","version_date":"1993-12-12","article_text":"1.Носителем суверенитета и единственным источником власти в Российской Федерации является ее многонациональный народ.\n\n2.Народ осуществляет свою власть непосредственно, а также через органы государственной власти и органы местного самоуправления.\n\n3.Высшим непосредственным выражением власти народа являются референдум и свободные выборы.\n\n4.Никто не может присваивать власть в Российской Федерации. Захват власти или присвоение властных полномочий преследуются по федеральному закону.","article_title":"Статья 3","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fb5783197b5f00871af588b8ea4972fc12e5ac1a10f712ea2822dbb24d292190"},{"code_id":"KONST_RF","article_number":"30","version_date":"1993-12-12","article_text":"1.Каждый имеет право на объединение, включая право создавать профессиональные союзы для защиты своих интересов. Свобода деятельности общественных объединений гарантируется.\n\n2.Никто не может быть принужден к вступлению в какое-либо объединение или пребыванию в нем.","article_title":"Статья 30","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f17112d46ac6a71c60c7bdcf0db77d5e8a25748778b0d76a14d5fb478d463da"},{"code_id":"KONST_RF","article_number":"31","version_date":"1993-12-12","article_text":"Граждане Российской Федерации имеют право собираться мирно, без оружия, проводить собрания, митинги и демонстрации, шествия и пикетирование.","article_title":"Статья 31","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e04d324cb4447c8020911793af4359a38a2a6686f87317ee3a61a7e13325793"},{"code_id":"KONST_RF","article_number":"32","version_date":"1993-12-12","article_text":"1.Граждане Российской Федерации имеют право участвовать в управлении делами государства как непосредственно, так и через своих представителей.\n\n2.Граждане Российской Федерации имеют право избирать и быть избранными в органы государственной власти и органы местного самоуправления, а также участвовать в референдуме.\n\n3.Не имеют права избирать и быть избранными граждане, признанные судом недееспособными, а также содержащиеся в местах лишения свободы по приговору суда.\n\n4.Граждане Российской Федерации имеют равный доступ к государственной службе.\n\n5.Граждане Российской Федерации имеют право участвовать в отправлении правосудия.","article_title":"Статья 32","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0c667640ac8ea2090f438ea835ca9307a0b489712d673ad04ae95e654ff3e3b"},{"code_id":"KONST_RF","article_number":"33","version_date":"1993-12-12","article_text":"Граждане Российской Федерации имеют право обращаться лично, а также направлять индивидуальные и коллективные обращения в государственные органы и органы местного самоуправления.","article_title":"Статья 33","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a94f8b4f76c8cd18494ca3c860fde285d0fe72db245bdfe4679cbfb3a00569c1"},{"code_id":"KONST_RF","article_number":"34","version_date":"1993-12-12","article_text":"1.Каждый имеет право на свободное использование своих способностей и имущества для предпринимательской и иной не запрещенной законом экономической деятельности.\n\n2.Не допускается экономическая деятельность, направленная на монополизацию и недобросовестную конкуренцию.","article_title":"Статья 34","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3650ea6720e04834bce9e70e5021de8b65d7f14354ea12377feae3e4ad202121"},{"code_id":"KONST_RF","article_number":"35","version_date":"1993-12-12","article_text":"1.Право частной собственности охраняется законом.\n\n2.Каждый вправе иметь имущество в собственности, владеть, пользоваться и распоряжаться им как единолично, так и совместно с другими лицами.\n\n3.Никто не может быть лишен своего имущества иначе как по решению суда. Принудительное отчуждение имущества для государственных нужд может быть произведено только при условии предварительного и равноценного возмещения.\n\n4.Право наследования гарантируется.","article_title":"Статья 35","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad73a9e20eae648f05ab0da28e1cd132ecd16bb2e140cf206b1d08458202c9bc"},{"code_id":"KONST_RF","article_number":"36","version_date":"1993-12-12","article_text":"1.Граждане и их объединения вправе иметь в частной собственности землю.\n\n2.Владение, пользование и распоряжение землей и другими природными ресурсами осуществляются их собственниками свободно, если это не наносит ущерба окружающей среде и не нарушает прав и законных интересов иных лиц.\n\n3.Условия и порядок пользования землей определяются на основе федерального закона.","article_title":"Статья 36","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86dabaf833dab5fb6dfe61ff161aab2812fb06718257d2fa7a3e3019c0175fd2"},{"code_id":"KONST_RF","article_number":"37","version_date":"1993-12-12","article_text":"1.Труд свободен. Каждый имеет право свободно распоряжаться своими способностями к труду, выбирать род деятельности и профессию.\n\n2.Принудительный труд запрещен.\n\n3.Каждый имеет право на труд в условиях, отвечающих требованиям безопасности и гигиены, на вознаграждение за труд без какой бы то ни было дискриминации и не ниже установленного федеральным законом минимального размера оплаты труда, а также право на защиту от безработицы.\n\n4.Признается право на индивидуальные и коллективные трудовые споры с использованием установленных федеральным законом способов их разрешения, включая право на забастовку.\n\n5.Каждый имеет право на отдых. Работающему по трудовому договору гарантируются установленные федеральным законом продолжительность рабочего времени, выходные и праздничные дни, оплачиваемый ежегодный отпуск.","article_title":"Статья 37","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d9dce34591f6fb0a43ecf0f0b1addde451809096b238bea31af3798e4c047e81"},{"code_id":"KONST_RF","article_number":"38","version_date":"1993-12-12","article_text":"1.Материнство и детство, семья находятся под защитой государства.\n\n2.Забота о детях, их воспитание — равное право и обязанность родителей.\n\n3.Трудоспособные дети, достигшие 18 лет, должны заботиться о нетрудоспособных родителях.","article_title":"Статья 38","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b9a767d510e9b327afefbe47c9c769f8d1c64257e6a356dfb0a1b18e7bb3d89"},{"code_id":"KONST_RF","article_number":"39","version_date":"1993-12-12","article_text":"1.Каждому гарантируется социальное обеспечение по возрасту, в случае болезни, инвалидности, потери кормильца, для воспитания детей и в иных случаях, установленных законом.\n\n2.Государственные пенсии и социальные пособия устанавливаются законом.\n\n3.Поощряются добровольное социальное страхование, создание дополнительных форм социального обеспечения и благотворительность.","article_title":"Статья 39","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0aaff46f40291641d325fce8b2f467811948bc0661adf5b3945691b7cc13d847"},{"code_id":"KONST_RF","article_number":"4","version_date":"1993-12-12","article_text":"1.Суверенитет Российской Федерации распространяется на всю ее территорию.\n\n2.Конституция Российской Федерации и федеральные законы имеют верховенство на всей территории Российской Федерации.\n\n3.Российская Федерация обеспечивает целостность и неприкосновенность своей территории.","article_title":"Статья 4","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"425cd544012f7ebf10de9f5dff54d233af1d008e9a936ed0581beea85235609f"},{"code_id":"KONST_RF","article_number":"40","version_date":"1993-12-12","article_text":"1.Каждый имеет право на жилище. Никто не может быть произвольно лишен жилища.\n\n2.Органы государственной власти и органы местного самоуправления поощряют жилищное строительство, создают условия для осуществления права на жилище.\n\n3.Малоимущим, иным указанным в законе гражданам, нуждающимся в жилище, оно предоставляется бесплатно или за доступную плату из государственных, муниципальных и других жилищных фондов в соответствии с установленными законом нормами.","article_title":"Статья 40","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"deb2e91189a59f17ec12bac8115adbd36da0aec6879bb54eea176c8a6cc45134"},{"code_id":"KONST_RF","article_number":"41","version_date":"1993-12-12","article_text":"1.Каждый имеет право на охрану здоровья и медицинскую помощь. Медицинская помощь в государственных и муниципальных учреждениях здравоохранения оказывается гражданам бесплатно за счет средств соответствующего бюджета, страховых взносов, других поступлений.\n\n2.В Российской Федерации финансируются федеральные программы охраны и укрепления здоровья населения, принимаются меры по развитию государственной, муниципальной, частной систем здравоохранения, поощряется деятельность, способствующая укреплению здоровья человека, развитию физической культуры и спорта, экологическому и санитарно-эпидемиологическому благополучию.\n\n3.Сокрытие должностными лицами фактов и обстоятельств, создающих угрозу для жизни и здоровья людей, влечет за собой ответственность в соответствии с федеральным законом.","article_title":"Статья 41","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d51b2de8b078b0e6e97cf1cb489b331d8eb69ae5493c1d95b61278b241b86e56"},{"code_id":"KONST_RF","article_number":"42","version_date":"1993-12-12","article_text":"Каждый имеет право на благоприятную окружающую среду, достоверную информацию о ее состоянии и на возмещение ущерба, причиненного его здоровью или имуществу экологическим правонарушением.","article_title":"Статья 42","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"102ca3c138f1ef7865f1bb7f543af44d362ee8a62e7bd9ad0ab450b14750c464"},{"code_id":"KONST_RF","article_number":"43","version_date":"1993-12-12","article_text":"1.Каждый имеет право на образование.\n\n2.Гарантируются общедоступность и бесплатность дошкольного, основного общего и среднего профессионального образования в государственных или муниципальных образовательных учреждениях и на предприятиях.\n\n3.Каждый вправе на конкурсной основе бесплатно получить высшее образование в государственном или муниципальном образовательном учреждении и на предприятии.\n\n4.Основное общее образование обязательно. Родители или лица, их заменяющие, обеспечивают получение детьми основного общего образования.\n\n5.Российская Федерация устанавливает федеральные государственные образовательные стандарты, поддерживает различные формы образования и самообразования.","article_title":"Статья 43","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"be3200f4fa74b472361d8e7ffd3af242a93f381a5f23798cfe98873aa30ef72f"},{"code_id":"KONST_RF","article_number":"44","version_date":"1993-12-12","article_text":"1.Каждому гарантируется свобода литературного, художественного, научного, технического и других видов творчества, преподавания. Интеллектуальная собственность охраняется законом.\n\n2.Каждый имеет право на участие в культурной жизни и пользование учреждениями культуры, на доступ к культурным ценностям.\n\n3.Каждый обязан заботиться о сохранении исторического и культурного наследия, беречь памятники истории и культуры.","article_title":"Статья 44","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd931868ace2a7fc9608f18fc87c7c5f1e5a352ae32666e8fcb295cc1ca3ec8e"},{"code_id":"KONST_RF","article_number":"45","version_date":"1993-12-12","article_text":"1.Государственная защита прав и свобод человека и гражданина в Российской Федерации гарантируется.\n\n2.Каждый вправе защищать свои права и свободы всеми способами, не запрещенными законом.","article_title":"Статья 45","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"79be89ee0f27ea513fed4bbc30f525982d0c283d4ac57ffea4ee6104220e38cf"},{"code_id":"KONST_RF","article_number":"46","version_date":"1993-12-12","article_text":"1.Каждому гарантируется судебная защита его прав и свобод.\n\n2.Решения и действия(или бездействие) органов государственной власти, органов местного самоуправления, общественных объединений и должностных лиц могут быть обжалованы в суд.\n\n3.Каждый вправе в соответствии с международными договорами Российской Федерации обращаться в межгосударственные органы по защите прав и свобод человека, если исчерпаны все имеющиеся внутригосударственные средства правовой защиты.","article_title":"Статья 46","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0dc2bc180552078a5642ec21de8dae02f507d32787f8811520ad749954362af1"},{"code_id":"KONST_RF","article_number":"47","version_date":"1993-12-12","article_text":"1.Никто не может быть лишен права на рассмотрение его дела в том суде и тем судьей, к подсудности которых оно отнесено законом.\n\n2.Обвиняемый в совершении преступления имеет право на рассмотрение его дела судом с участием присяжных заседателей в случаях, предусмотренных федеральным законом.","article_title":"Статья 47","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f5f98e64f5289d3e7e88bc20a8ea755193daf6f54015df51a6e97975355204d2"},{"code_id":"KONST_RF","article_number":"48","version_date":"1993-12-12","article_text":"1.Каждому гарантируется право на получение квалифицированной юридической помощи. В случаях, предусмотренных законом, юридическая помощь оказывается бесплатно.\n\n2.Каждый задержанный, заключенный под стражу, обвиняемый в совершении преступления имеет право пользоваться помощью адвоката(защитника) с момента соответственно задержания, заключения под стражу или предъявления обвинения.","article_title":"Статья 48","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f7dcc5273d82d12dc4eeee9cba52589c77a613e511adc41552e70361aa6f7dac"},{"code_id":"KONST_RF","article_number":"49","version_date":"1993-12-12","article_text":"1.Каждый обвиняемый в совершении преступления считается невиновным, пока его виновность не будет доказана в предусмотренном федеральным законом порядке и установлена вступившим в законную силу приговором суда.\n\n2.Обвиняемый не обязан доказывать свою невиновность.\n\n3.Неустранимые сомнения в виновности лица толкуются в пользу обвиняемого.","article_title":"Статья 49","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"26b0f2d6af4f9988c96c7f5fd03a335f99e08202677d4bee005291bb1668fce4"},{"code_id":"KONST_RF","article_number":"5","version_date":"1993-12-12","article_text":"1.Российская Федерация состоит из республик, краев, областей, городов федерального значения, автономной области, автономных округов — равноправных субъектов Российской Федерации.\n\n2.Республика(государство) имеет свою конституцию и законодательство. Край, область, город федерального значения, автономная область, автономный округ имеет свой устав и законодательство.\n\n3.Федеративное устройство Российской Федерации основано на ее государственной целостности, единстве системы государственной власти, разграничении предметов ведения и полномочий между органами государственной власти Российской Федерации и органами государственной власти субъектов Российской Федерации, равноправии и самоопределении народов в Российской Федерации.\n\n4.Во взаимоотношениях с федеральными органами государственной власти все субъекты Российской Федерации между собой равноправны.","article_title":"Статья 5","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f924511a845ba922d9a51b037766319860acd08f379b9ac164a9d3ceecd79b87"},{"code_id":"KONST_RF","article_number":"50","version_date":"1993-12-12","article_text":"1.Никто не может быть повторно осужден за одно и то же преступление.\n\n2.При осуществлении правосудия не допускается использование доказательств, полученных с нарушением федерального закона.\n\n3.Каждый осужденный за преступление имеет право на пересмотр приговора вышестоящим судом в порядке, установленном федеральным законом, а также право просить о помиловании или смягчении наказания.","article_title":"Статья 50","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b749116841077ce1fabc4625f073dfacd91f11b59b762002032ae560189fe49b"},{"code_id":"KONST_RF","article_number":"51","version_date":"1993-12-12","article_text":"1.Никто не обязан свидетельствовать против себя самого, своего супруга и близких родственников, круг которых определяется федеральным законом.\n\n2.Федеральным законом могут устанавливаться иные случаи освобождения от обязанности давать свидетельские показания.","article_title":"Статья 51","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"af047289203d56a2ff98d564c9059347e11f6ffa8eaf1e524d0e721afbe323c7"},{"code_id":"KONST_RF","article_number":"52","version_date":"1993-12-12","article_text":"Права потерпевших от преступлений и злоупотреблений властью охраняются законом. Государство обеспечивает потерпевшим доступ к правосудию и компенсацию причиненного ущерба.","article_title":"Статья 52","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"05412ad0d1b877903ad03ffc9adaf1189750b5d978c1084abf39a3f725da293c"},{"code_id":"KONST_RF","article_number":"53","version_date":"1993-12-12","article_text":"Каждый имеет право на возмещение государством вреда, причиненного незаконными действиями(или бездействием) органов государственной власти или их должностных лиц.","article_title":"Статья 53","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"971199fd5d2559708d3ccd85e146eabe8bc415558e55337aeb69939a16672530"},{"code_id":"KONST_RF","article_number":"54","version_date":"1993-12-12","article_text":"1.Закон, устанавливающий или отягчающий ответственность, обратной силы не имеет.\n\n2.Никто не может нести ответственность за деяние, которое в момент его совершения не признавалось правонарушением. Если после совершения правонарушения ответственность за него устранена или смягчена, применяется новый закон.","article_title":"Статья 54","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ebd9bba6829efd2f36b450c7393743b0a6c31d3a0d531d0f11959142971db818"},{"code_id":"KONST_RF","article_number":"55","version_date":"1993-12-12","article_text":"1.Перечисление в Конституции Российской Федерации основных прав и свобод не должно толковаться как отрицание или умаление других общепризнанных прав и свобод человека и гражданина.\n\n2.В Российской Федерации не должны издаваться законы, отменяющие или умаляющие права и свободы человека и гражданина.\n\n3.Права и свободы человека и гражданина могут быть ограничены федеральным законом только в той мере, в какой это необходимо в целях защиты основ конституционного строя, нравственности, здоровья, прав и законных интересов других лиц, обеспечения обороны страны и безопасности государства.","article_title":"Статья 55","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c13b22b8cf8892d2076e8dc76614d52ca59bb186be8975f17987369f07ac629e"},{"code_id":"KONST_RF","article_number":"56","version_date":"1993-12-12","article_text":"1.В условиях чрезвычайного положения для обеспечения безопасности граждан и защиты конституционного строя в соответствии с федеральным конституционным законом могут устанавливаться отдельные ограничения прав и свобод с указанием пределов и срока их действия.\n\n2.Чрезвычайное положение на всей территории Российской Федерации и в ее отдельных местностях может вводиться при наличии обстоятельств и в порядке, установленных федеральным конституционным законом.\n\n3.Не подлежат ограничению права и свободы, предусмотренные статьями 20, 21, 23(часть 1), 24, 28, 34(часть 1), 40(часть 1), 46 — 54 Конституции Российской Федерации.","article_title":"Статья 56","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"08fdcf481862283107f37e1b38c31c26cb2f6b36e6adbcec1483f4ce6a0b6b53"},{"code_id":"KONST_RF","article_number":"57","version_date":"1993-12-12","article_text":"Каждый обязан платить законно установленные налоги и сборы. Законы, устанавливающие новые налоги или ухудшающие положение налогоплательщиков, обратной силы не имеют.","article_title":"Статья 57","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"32b921b95909074032e58069b05396f65b01decec310484564bbac374534ea16"},{"code_id":"KONST_RF","article_number":"58","version_date":"1993-12-12","article_text":"Каждый обязан сохранять природу и окружающую среду, бережно относиться к природным богатствам.","article_title":"Статья 58","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e3698d5329a74d6de73c22fb9c604a03a570f8d73a3c17080afc1f80721d3ee4"},{"code_id":"KONST_RF","article_number":"59","version_date":"1993-12-12","article_text":"1.Защита Отечества является долгом и обязанностью гражданина Российской Федерации.\n\n2.Гражданин Российской Федерации несет военную службу в соответствии с федеральным законом.\n\n3.Гражданин Российской Федерации в случае, если его убеждениям или вероисповеданию противоречит несение военной службы, а также в иных установленных федеральным законом случаях имеет право на замену ее альтернативной гражданской службой.","article_title":"Статья 59","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4da6fbc79322eea45bf057a161a9287fb3a98562e8760f7bc6f2d568797ca98"},{"code_id":"KONST_RF","article_number":"6","version_date":"1993-12-12","article_text":"1.Гражданство Российской Федерации приобретается и прекращается в соответствии с федеральным законом, является единым и равным независимо от оснований приобретения.\n\n2.Каждый гражданин Российской Федерации обладает на ее территории всеми правами и свободами и несет равные обязанности, предусмотренные Конституцией Российской Федерации.\n\n3.Гражданин Российской Федерации не может быть лишен своего гражданства или права изменить его.","article_title":"Статья 6","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"39924c734667f00993d48df5c5a25202a77a00007ca492e6c08751da57b2b1d8"},{"code_id":"KONST_RF","article_number":"60","version_date":"1993-12-12","article_text":"Гражданин Российской Федерации может самостоятельно осуществлять в полном объеме свои права и обязанности с 18 лет.","article_title":"Статья 60","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27e9987f653112542285d192f819134b14441e0ddf531acd0106f66dac26c035"},{"code_id":"KONST_RF","article_number":"61","version_date":"1993-12-12","article_text":"1.Гражданин Российской Федерации не может быть выслан за пределы Российской Федерации или выдан другому государству.\n\n2.Российская Федерация гарантирует своим гражданам защиту и покровительство за ее пределами.","article_title":"Статья 61","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"76bc61af92e077ca015f5c023fa25519a6781eaa0c1eedd668592b32ddf5ccdf"},{"code_id":"KONST_RF","article_number":"62","version_date":"1993-12-12","article_text":"1.Гражданин Российской Федерации может иметь гражданство иностранного государства(двойное гражданство) в соответствии с федеральным законом или международным договором Российской Федерации.\n\n2.Наличие у гражданина Российской Федерации гражданства иностранного государства не умаляет его прав и свобод и не освобождает от обязанностей, вытекающих из российского гражданства, если иное не предусмотрено федеральным законом или международным договором Российской Федерации.\n\n3.Иностранные граждане и лица без гражданства пользуются в Российской Федерации правами и несут обязанности наравне с гражданами Российской Федерации, кроме случаев, установленных федеральным законом или международным договором Российской Федерации.","article_title":"Статья 62","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3578263482f3cdf0801d0301ad7d9d9012b386e952abc407419ad35c9f0170a2"},{"code_id":"KONST_RF","article_number":"63","version_date":"1993-12-12","article_text":"1.Российская Федерация предоставляет политическое убежище иностранным гражданам и лицам без гражданства в соответствии с общепризнанными нормами международного права.\n\n2.В Российской Федерации не допускается выдача другим государствам лиц, преследуемых за политические убеждения, а также за действия(или бездействие), не признаваемые в Российской Федерации преступлением. Выдача лиц, обвиняемых в совершении преступления, а также передача осужденных для отбывания наказания в других государствах осуществляются на основе федерального закона или международного договора Российской Федерации.","article_title":"Статья 63","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ee06123ce7c87829aa996ababe00fd4e0834e0fbe2782420bbd7a0f7d118475f"},{"code_id":"KONST_RF","article_number":"64","version_date":"1993-12-12","article_text":"Положения настоящей главы составляют основы правового статуса личности в Российской Федерации и не могут быть изменены иначе как в порядке, установленном настоящей Конституцией.","article_title":"Статья 64","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"59b9890c954a0d1b9bed953ecadb18e3ef6c55141fd6dcd377f529e2eb758e84"},{"code_id":"KONST_RF","article_number":"65","version_date":"1993-12-12","article_text":"1.В составе Российской Федерации находятся субъекты Российской Федерации:\n\nРеспублика Адыгея(Адыгея), Республика Алтай, Республика Башкортостан, Республика Бурятия, Республика Дагестан,Донецкая Народная Республика,Республика Ингушетия, Кабардино-Балкарская Республика,Республика Калмыкия, Карачаево-Черкесская Республика, Республика Карелия, Республика Коми,Республика Крым,Луганская Народная Республика, Республика Марий Эл, Республика Мордовия, Республика Саха(Якутия),Республика Северная Осетия — Алания, Республика Татарстан(Татарстан), Республика Тыва, Удмуртская Республика, Республика Хакасия, Чеченская Республика, Чувашская Республика —Чувашия;\n\nРедакция статей, частей и пунктов, помеченных символом <*>, приведена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 14 марта 2020 г. № 1-ФКЗ «О совершенствовании регулирования отдельных вопросов организации и функционирования публичной власти». Изменения, внесенные названным Законом Российской Федерации о поправке к Конституции Российской Федерации, вступают в силу со дня официального опубликования результатов общероссийского голосования по вопросу одобрения изменений в Конституцию Российской Федерации.Наименование нового субъекта Российской Федерации - Донецкая Народная Республика - дано в соответствии с Федеральным конституционным законом от 4 октября 2022 г. No 5-ФКЗ \"О принятии в Российскую Федерацию Донецкой Народной Республики и образовании в составе Российской Федерации нового субъекта - Донецкой Народной Республики\" (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2022, 5 октября, No 0001202210050005).Новое наименование  Республики  дано в соответствии с Указом Президента Российской Федерации от 9 января 1996 г. № 20«О включении новых наименований субъектов Российской Федерации в статью 65 Конституции Российской Федерации»(Собрание законодательства Российской Федерации, 1996, № 3, ст. 152).Новое наименование Республики дано в соответствии с Указом Президента Российской Федерации от 10 февраля 1996 г. № 173«О включении нового наименования субъекта Российской Федерации в статью 65 Конституции Российской Федерации»(Собрание законодательства Российской Федерации, 1996, № 7, ст. 676).Наименование нового субъекта Российской Федерации — Республика Крым — дано в соответствии с Федеральным конституционным законом от 21 марта 2014 г. № 6-ФКЗ«О принятии в Российскую Федерацию Республики Крым и образовании в составе Российской Федерации новых субъектов — Республики Крым и города федерального значения Севастополя»(Собрание законодательства Российской Федерации, 2014, № 12, ст. 1201).Наименование нового субъекта Российской Федерации - Луганская Народная Республика - дано в соответствии с Федеральным конституционным законом от 4 октября 2022 г. No 6-ФКЗ \"О принятии в Российскую Федерацию Луганской Народной Республики и образовании в составе Российской Федерации нового субъекта - Луганской Народной Республики\" (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2022, 5 октября, No 0001202210050006).Новое наименование Республики дано в соответствии с Указом Президента Российской Федерации от 9 января 1996 г. № 20«О включении новых наименований субъектов Российской Федерации в статью 65 Конституции Российской Федерации»(Собрание законодательства Российской Федерации, 1996, № 3, ст. 152).Новое наименование  Республики дано в соответствии с Указом Президента Российской Федерации от 9 июня 2001 г. № 679«О включении нового наименования субъекта Российской Федерации в статью 65 Конституции Российской Федерации»(Собрание законодательства Российской Федерации, 2001, № 24, ст. 2421).\n\nАлтайский край,Забайкальский край,Камчатский край, Краснодарский край,Красноярский край,Пермский край, Приморский край, Ставропольский край, Хабаровский край;\n\nНаименование нового субъекта Российской Федерации — Забайкальский край — дано в связи с его образованием с 1 марта 2008 г., а наименования прекративших существование с 1 марта 2008 г. в качестве субъектов Российской Федерации Читинской области и Агинского Бурятского автономного округа исключены из части 1 статьи 65 Конституции Российской Федерации на основании Федерального конституционного закона от 21 июля 2007 г. № 5-ФКЗ«Об образовании в составе Российской Федерации нового субъекта Российской Федерации в результате объединения Читинской области и Агинского Бурятского автономного округа»(Собрание законодательства Российской Федерации, 2007, № 30, ст. 3745).Новое наименование области дано в соответствии с Указом Президента Российской Федерации от 27 марта 2019 г. № 130 «О включении нового наименования субъекта Российской Федерации в статью 65 Конституции Российской Федерации» (Собрание законодательства Российской Федерации, 2019, № 13, ст. 1390).Наименование нового субъекта Российской Федерации - Херсонская область - дано в соответствии с Федеральным конституционным законом от 4 октября 2022 г. No 8-ФКЗ \"О принятии в Российскую Федерацию Херсонской области и образовании в составе Российской Федерации нового субъекта - Херсонской области\" (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2022, 5 октября, No 0001202210050008).Наименование нового субъекта Российской Федерации — Камчатский край — дано в связи с его образованием с 1 июля 2007 г., а наименования прекративших существование с 1 июля 2007 г. в качестве субъектов Российской Федерации Камчатской области и Корякского автономного округа исключены из части 1 статьи 65 Конституции Российской Федерации на основании Федерального конституционного закона от 12 июля 2006 г. № 2-ФКЗ«Об образовании в составе Российской Федерации нового субъекта Российской Федерации в результате объединения Камчатской области и Корякского автономного округа»(Собрание законодательства Российской Федерации, 2006, № 29, ст. 3119).Наименование нового субъекта Российской Федерации — Красноярский край — дано в связи с его образованием с 1 января 2007 г., а наименования прекративших существование с 1 января 2007 г. в качестве субъектов Российской Федерации Таймырского (Долгано-Ненецкого) автономного округа и Эвенкийского автономного округа исключены из части 1 статьи 65 Конституции Российской Федерации на основании Федерального конституционного закона от 14 октября 2005 г. № 6-ФКЗ «Об образовании в составе Российской Федерации нового субъекта Российской Федерации в результате объединения Красноярского края, Таймырского (Долгано-Ненецкого) автономного округа и Эвенкийского автономного округа» (Собрание законодательства Российской Федерации, 2005, № 42, ст. 4212).Наименование нового субъекта Российской Федерации — Пермский край — дано в связи с его образованием с 1 декабря 2005 г., а наименования прекративших существование с 1 декабря 2005 г. в качестве субъектов Российской Федерации Пермской области и Коми-Пермяцкого автономного округа исключены из части 1 статьи 65 Конституции Российской Федерации на основании Федерального конституционного закона от 25 марта 2004 г. № 1-ФКЗ«Об образовании в составе Российской Федерации нового субъекта Российской Федерации в результате объединения Пермской области и Коми-Пермяцкого автономного округа»(Собрание законодательства Российской Федерации, 2004, № 13, ст. 1110).\n\nАмурская область, Архангельская область, Астраханская область, Белгородская область, Брянская область, Владимирская область, Волгоградская область, Вологодская область, Воронежская область,Запорожская область, Ивановская область,Иркутская область, Калининградская область, Калужская область,Кемеровская область — Кузбасс, Кировская область, Костромская область, Курганская область, Курская область, Ленинградская область, Липецкая область, Магаданская область, Московская область, Мурманская область, Нижегородская область, Новгородская область, Новосибирская область, Омская область, Оренбургская область, Орловская область, Пензенская область, Псковская область, Ростовская область, Рязанская область, Самарская область, Саратовская область, Сахалинская область, Свердловская область, Смоленская область, Тамбовская область, Тверская область, Томская область, Тульская область, Тюменская область, Ульяновская область,Херсонская область, Челябинская область, Ярославская область;\n\nНаименование нового субъекта Российской Федерации — Иркутская область — дано в связи с его образованием с 1 января 2008 г., а наименование прекратившего существование с 1 января 2008 г. в качестве субъекта Российской Федерации Усть-Ордынского Бурятского автономного округа исключено из части 1 статьи 65 Конституции Российской Федерации на основании Федерального конституционного закона от 30 декабря 2006 г. № 6-ФКЗ«Об образовании в составе Российской Федерации нового субъекта Российской Федерации в результате объединения Иркутской области и Усть-Ордынского Бурятского автономного округа»(Собрание законодательства Российской Федерации, 2007, № 1, ст. 1).Наименование нового субъекта Российской Федерации - Запорожская область - дано в соответствии с Федеральным конституционным законом от 4 октября 2022 г. No 7-ФКЗ \"О принятии в Российскую Федерацию Запорожской области и образовании в составе Российской Федерации нового субъекта - Запорожской области\" (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2022, 5 октября, No 0001202210050007).\n\nМосква, Санкт-Петербург,Севастополь— города федерального значения;\n\nНаименование нового субъекта Российской Федерации — город федерального значения Севастополь — дано в соответствии с Федеральным конституционным законом от 21 марта 2014 г. № 6-ФКЗ«О принятии в Российскую Федерацию Республики Крым и образовании в составе Российской Федерации новых субъектов — Республики Крым и города федерального значения Севастополя»(Собрание законодательства Российской Федерации, 2014, № 12. ст. 1201).\n\nЕврейская автономная область;\n\nНенецкий автономный округ, Ханты-Мансийский автономныйокруг —Югра, Чукотский автономный округ, Ямало-Ненецкий автономный округ.\n\nНовое наименование автономного округа дано в соответствии с Указом Президента Российской Федерации от 25 июля 2003 г. № 841«О включении нового наименования субъекта Российской Федерации в статью 65 Конституции Российской Федерации»(Собрание законодательства Российской Федерации, 2003, № 30. ст. 3051).\n\n2.Принятие в Российскую Федерацию и образование в ее составе нового субъекта осуществляются в порядке, установленном федеральным конституционным законом.","article_title":"Статья 65","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"435216e9dca146dc1d9dc81e9ac5ab4eac2410a9587885b4c6451aa282c81884"},{"code_id":"KONST_RF","article_number":"66","version_date":"1993-12-12","article_text":"1.Статус республики определяется Конституцией Российской Федерации и конституцией республики.\n\n2.Статус края, области, города федерального значения, автономной области, автономного округа определяется Конституцией Российской Федерации и уставом края, области, города федерального значения, автономной области, автономного округа, принимаемым законодательным(представительным) органом соответствующего субъекта Российской Федерации.\n\n3.По представлению законодательных и исполнительных органов автономной области, автономного округа может быть принят федеральный закон об автономной области, автономном округе.\n\n4.Отношения автономных округов, входящих в состав края или области, могут регулироваться федеральным законом и договором между органами государственной власти автономного округа и, соответственно, органами государственной власти края или области.\n\n5.Статус субъекта Российской Федерации может быть изменен по взаимному согласию Российской Федерации и субъекта Российской Федерации в соответствии с федеральным конституционным законом.","article_title":"Статья 66","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f1d7e8dee16602b96b2acb6038b7488b3d972e8b8cc700687626afe916750be"},{"code_id":"KONST_RF","article_number":"67","version_date":"1993-12-12","article_text":"1.Территория Российской Федерации включает в себя территории ее субъектов, внутренние воды и территориальное море, воздушное пространство над ними. На территории Российской Федерации в соответствии с федеральным законом могут быть созданы федеральные территории. Организация публичной власти на федеральных территориях устанавливается указанным федеральным законом.*\n\n2.Российская Федерация обладает суверенными правами и осуществляет юрисдикцию на континентальном шельфе и в исключительной экономической зоне Российской Федерации в порядке, определяемом федеральным законом и нормами международного права.\n\n21.Российская Федерация обеспечивает защиту своего суверенитета и территориальной целостности. Действия (за исключением делимитации, демаркации, редемаркации государственной границы Российской Федерации с сопредельными государствами), направленные на отчуждение части территории Российской Федерации, а также призывы к таким действиям не допускаются.*i\n\n3.Границы между субъектами Российской Федерации могут быть изменены с их взаимного согласия.","article_title":"Статья 67","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b59362f234cda1999e3db1e035a0479cb0dc3122e9a1f2de4fb424c5519a2101"},{"code_id":"KONST_RF","article_number":"68","version_date":"1993-12-12","article_text":"1.Государственным языком Российской Федерации на всей ее территории является русский язык как язык государствообразующего народа, входящего в многонациональный союз равноправных народов Российской Федерации.\n\n2.Республики вправе устанавливать свои государственные языки. В органах государственной власти, органах местного самоуправления, государственных учреждениях республик они употребляются наряду с государственным языком Российской Федерации.\n\n3.Российская Федерация гарантирует всем ее народам право на сохранение родного языка, создание условий для его изучения и развития.\n\n4.Культура в Российской Федерации является уникальным наследием ее многонационального народа. Культура поддерживается и охраняется государством.","article_title":"Статья 68","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e59b905a0016ca53551a42e2f805e67a71e96827503b0483ae2d8b80bb640324"},{"code_id":"KONST_RF","article_number":"69","version_date":"1993-12-12","article_text":"1.Российская Федерация гарантирует права коренных малочисленных народов в соответствии с общепризнанными принципами и нормами международного права и международными договорами Российской Федерации.\n\n2.Государство защищает культурную самобытность всех народов и этнических общностей Российской Федерации, гарантирует сохранение этнокультурного и языкового многообразия.\n\n3.Российская Федерация оказывает поддержку соотечественникам, проживающим за рубежом, в осуществлении их прав, обеспечении защиты их интересов и сохранении общероссийской культурной идентичности.","article_title":"Статья 69","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"152978aa385986167631b1e88d7753381156d5848bc6c31e6b6901e3da683824"},{"code_id":"KONST_RF","article_number":"7","version_date":"1993-12-12","article_text":"1.Российская Федерация — социальное государство, политика которого направлена на создание условий, обеспечивающих достойную жизнь и свободное развитие человека.\n\n2.В Российской Федерации охраняются труд и здоровье людей, устанавливается гарантированный минимальный размер оплаты труда, обеспечивается государственная поддержка семьи, материнства, отцовства и детства, инвалидов и пожилых граждан, развивается система социальных служб, устанавливаются государственные пенсии, пособия и иные гарантии социальной защиты.","article_title":"Статья 7","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"552cf799d6391634e62c604d9c7156910cb2125d0dd7af37fec80f0f24382a03"},{"code_id":"KONST_RF","article_number":"70","version_date":"1993-12-12","article_text":"1.Государственные флаг, герб и гимн Российской Федерации, их описание и порядок официального использования устанавливаются федеральным конституционным законом.\n\n2.Столицей Российской Федерации является город Москва. Статус столицы устанавливается федеральным законом. Местом постоянного пребывания отдельных федеральных органов государственной власти может быть другой город, определенный федеральным конституционным законом.","article_title":"Статья 70","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"17006021c5776119b8b223e02e34e49670b5e03ca3e021dcc3e1a724e03aae66"},{"code_id":"KONST_RF","article_number":"71","version_date":"1993-12-12","article_text":"В ведении Российской Федерации находятся:\n\nа)принятие и изменение Конституции Российской Федерации и федеральных законов, контроль за их соблюдением;\n\nб)федеративное устройство и территория Российской Федерации;\n\nв)регулирование и защита прав и свобод человека и гражданина; гражданство в Российской Федерации; регулирование и защита прав национальных меньшинств;\n\nг)организация публичной власти; установление системы федеральных органов законодательной, исполнительной и судебной власти, порядка их организации и деятельности; формирование федеральных органов государственной власти;*\n\nд)федеральная государственная собственность и управление ею;\n\nе)установление основ федеральной политики и федеральные программы в области государственного, экономического, экологического, научно-технологического, социального, культурного и национального развития Российской Федерации; установление единых правовых основ системы здравоохранения, системы воспитания и образования, в том числе непрерывного образования;*\n\nж)установление правовых основ единого рынка; финансовое, валютное, кредитное, таможенное регулирование, денежная эмиссия, основы ценовой политики; федеральные экономические службы, включая федеральные банки;\n\nз)федеральный бюджет; федеральные налоги и сборы; федеральные фонды регионального развития;\n\nи)федеральные энергетические системы, ядерная энергетика, расщепляющиеся материалы; федеральные транспорт, пути сообщения, информация, информационные технологии и связь; космическая деятельность;*\n\nк)внешняя политика и международные отношения Российской Федерации, международные договоры Российской Федерации; вопросы войны и мира;\n\nл)внешнеэкономические отношения Российской Федерации;\n\nм)оборона и безопасность; оборонное производство; определение порядка продажи и покупки оружия, боеприпасов, военной техники и другого военного имущества; производство ядовитых веществ, наркотических средств и порядок их использования; обеспечение безопасности личности, общества и государства при применении информационных технологий, обороте цифровых данных;*\n\nн)определение статуса и защита государственной границы, территориального моря, воздушного пространства, исключительной экономической зоны и континентального шельфа Российской Федерации;\n\nо)судоустройство; прокуратура; уголовное и уголовно-исполнительное законодательство; амнистия и помилование; гражданское законодательство; процессуальное законодательство; правовое регулирование интеллектуальной собственности;\n\nРедакция пункта «о» приведена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 5 февраля 2014 г. № 2-ФКЗ «О Верховном Суде Российской Федерации и прокуратуре Российской Федерации», вступившим в силу со дня его официального опубликования 6 февраля 2014 г. (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2014, 6 февраля, № 0001201402060001).\n\nп)федеральное коллизионное право;\n\nр)метрологическая служба, стандарты, эталоны, метрическая система и исчисление времени; геодезия и картография; наименования географических объектов; метеорологическая служба; официальный статистический и бухгалтерский учет;*\n\nс)государственные награды и почетные звания Российской Федерации;\n\nт)федеральная государственная служба; установление ограничений для замещения государственных и муниципальных должностей, должностей государственной и муниципальной службы, в том числе ограничений, связанных с наличием гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства, а также ограничений, связанных с открытием и наличием счетов (вкладов), хранением наличных денежных средств и ценностей в иностранных банках, расположенных за пределами территории Российской Федерации.*","article_title":"Статья 71","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"67233c4ae9a399a70c5c8302d10a15930285c1565c5830baabd9d12f40b27e22"},{"code_id":"KONST_RF","article_number":"72","version_date":"1993-12-12","article_text":"1.В совместном ведении Российской Федерации и субъектов Российской Федерации находятся:\n\nа)обеспечение соответствия конституций и законов республик, уставов, законов и иных нормативных правовых актов краев, областей, городов федерального значения, автономной области, автономных округов Конституции Российской Федерации и федеральным законам;\n\nб)защита прав и свобод человека и гражданина; защита прав национальных меньшинств; обеспечение законности, правопорядка, общественной безопасности; режим пограничных зон;\n\nв)вопросы владения, пользования и распоряжения землей, недрами, водными и другими природными ресурсами;\n\nг)разграничение государственной собственности;\n\nд)природопользование; сельское хозяйство; охрана окружающей среды и обеспечение экологической безопасности; особо охраняемые природные территории; охрана памятников истории и культуры;*\n\nе)общие вопросы воспитания, образования, науки, культуры, физической культуры и спорта, молодежной политики;*\n\nж)координация вопросов здравоохранения, в том числе обеспечение оказания доступной и качественной медицинской помощи, сохранение и укрепление общественного здоровья, создание условий для ведения здорового образа жизни, формирования культуры ответственного отношения граждан к своему здоровью; социальная защита, включая социальное обеспечение;*\n\nж1)защита семьи, материнства, отцовства и детства; защита института брака как союза мужчины и женщины; создание условий для достойного воспитания детей в семье, а также для осуществления совершеннолетними детьми обязанности заботиться о родителях;*\n\nз)осуществление мер по борьбе с катастрофами, стихийными бедствиями, эпидемиями, ликвидация их последствий;\n\nи)установление общих принципов налогообложения и сборов в Российской Федерации;\n\nк)административное, административно-процессуальное, трудовое, семейное, жилищное, земельное, водное, лесное законодательство, законодательство о недрах, об охране окружающей среды;\n\nл)кадры судебных и правоохранительных органов; адвокатура, нотариат;\n\nм)защита исконной среды обитания и традиционного образа жизни малочисленных этнических общностей;\n\nн)установление общих принципов организации системы органов государственной власти и местного самоуправления;\n\nо)координация международных и внешнеэкономических связей субъектов Российской Федерации, выполнение международных договоров Российской Федерации.\n\n2.Положения настоящей статьи в равной мере распространяются на республики, края, области, города федерального значения, автономную область, автономные округа.","article_title":"Статья 72","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c61a77d70076a259faa72caa959762b0f08524ad6100d498ac7229c010c3bf72"},{"code_id":"KONST_RF","article_number":"73","version_date":"1993-12-12","article_text":"Вне пределов ведения Российской Федерации и полномочий Российской Федерации по предметам совместного ведения Российской Федерации и субъектов Российской Федерации субъекты Российской Федерации обладают всей полнотой государственной власти.","article_title":"Статья 73","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1b8a8779b48de1876ed20590fa1f1045894378aac7ba486cacfce14fd71c4663"},{"code_id":"KONST_RF","article_number":"74","version_date":"1993-12-12","article_text":"1.На территории Российской Федерации не допускается установление таможенных границ, пошлин, сборов и каких-либо иных препятствий для свободного перемещения товаров, услуг и финансовых средств.\n\n2.Ограничения перемещения товаров и услуг могут вводиться в соответствии с федеральным законом, если это необходимо для обеспечения безопасности, защиты жизни и здоровья людей, охраны природы и культурных ценностей.","article_title":"Статья 74","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0a2cb5b3c8983cfa3b9b9eb3871afc75cce482a5c573f4444301c44f1d5a17a"},{"code_id":"KONST_RF","article_number":"75","version_date":"1993-12-12","article_text":"1.Денежной единицей в Российской Федерации является рубль. Денежная эмиссия осуществляется исключительно Центральным банком Российской Федерации. Введение и эмиссия других денег в Российской Федерации не допускаются.\n\n2.Защита и обеспечение устойчивости рубля — основная функция Центрального банка Российской Федерации, которую он осуществляет независимо от других органов государственной власти.\n\n3.Система налогов, взимаемых в федеральный бюджет, и общие принципы налогообложения и сборов в Российской Федерации устанавливаются федеральным законом.\n\n4.Государственные займы выпускаются в порядке, определяемом федеральным законом, и размещаются на добровольной основе.\n\n5.Российская Федерация уважает труд граждан и обеспечивает защиту их прав. Государством гарантируется минимальный размер оплаты труда не менее величины прожиточного минимума трудоспособного населения в целом по Российской Федерации.\n\n6.В Российской Федерации формируется система пенсионного обеспечения граждан на основе принципов всеобщности, справедливости и солидарности поколений и поддерживается ее эффективное функционирование, а также осуществляется индексация пенсий не реже одного раза в год в порядке, установленном федеральным законом.\n\n7.В Российской Федерации в соответствии с федеральным законом гарантируются обязательное социальное страхование, адресная социальная поддержка граждан и индексация социальных пособий и иных социальных выплат.","article_title":"Статья 75","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"59042b9cd92971358f67d3ef0c68327306b71fae9017f53705f67d5859636827"},{"code_id":"KONST_RF","article_number":"76","version_date":"1993-12-12","article_text":"1.По предметам ведения Российской Федерации принимаются федеральные конституционные законы и федеральные законы, имеющие прямое действие на всей территории Российской Федерации.\n\n2.По предметам совместного ведения Российской Федерации и субъектов Российской Федерации издаются федеральные законы и принимаемые в соответствии с ними законы и иные нормативные правовые акты субъектов Российской Федерации.\n\n3.Федеральные законы не могут противоречить федеральным конституционным законам.\n\n4.Вне пределов ведения Российской Федерации, совместного ведения Российской Федерации и субъектов Российской Федерации республики, края, области, города федерального значения, автономная область и автономные округа осуществляют собственное правовое регулирование, включая принятие законов и иных нормативных правовых актов.\n\n5.Законы и иные нормативные правовые акты субъектов Российской Федерации не могут противоречить федеральным законам, принятым в соответствии с частями первой и второй настоящей статьи. В случае противоречия между федеральным законом и иным актом, изданным в Российской Федерации, действует федеральный закон.\n\n6.В случае противоречия между федеральным законом и нормативным правовым актом субъекта Российской Федерации, изданным в соответствии с частью четвертой настоящей статьи, действует нормативный правовой акт субъекта Российской Федерации.","article_title":"Статья 76","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4faf867df5ad90066ae70b82cf7a0d4881ed292b3d1cfed64ec6b7ba791c62ed"},{"code_id":"KONST_RF","article_number":"77","version_date":"1993-12-12","article_text":"1.Система органов государственной власти республик, краев, областей, городов федерального значения, автономной области, автономных округов устанавливается субъектами Российской Федерации самостоятельно в соответствии с основами конституционного строя Российской Федерации и общими принципами организации представительных и исполнительных органов государственной власти, установленными федеральным законом.\n\n2.В пределах ведения Российской Федерации и полномочий Российской Федерации по предметам совместного ведения Российской Федерации и субъектов Российской Федерации федеральные органы исполнительной власти и органы исполнительной власти субъектов Российской Федерации образуют единую систему исполнительной власти в Российской Федерации.\n\n3.Высшим должностным лицом субъекта Российской Федерации (руководителем высшего исполнительного органа государственной власти субъекта Российской Федерации) может быть гражданин Российской Федерации, достигший 30 лет, постоянно проживающий в Российской Федерации, не имеющий гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Высшему должностному лицу субъекта Российской Федерации (руководителю высшего исполнительного органа государственной власти субъекта Российской Федерации) в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации. Федеральным законом могут быть установлены дополнительные требования к высшему должностному лицу субъекта Российской Федерации (руководителю высшего исполнительного органа государственной власти субъекта Российской Федерации).*","article_title":"Статья 77","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3398103d0c4c85e0665e98532b30e79014b958c86bc85805d9043b35b84434c2"},{"code_id":"KONST_RF","article_number":"78","version_date":"1993-12-12","article_text":"1.Федеральные органы исполнительной власти для осуществления своих полномочий могут создавать свои территориальные органы и назначать соответствующих должностных лиц.\n\n2.Федеральные органы исполнительной власти по соглашению с органами исполнительной власти субъектов Российской Федерации могут передавать им осуществление части своих полномочий, если это не противоречит Конституции Российской Федерации и федеральным законам.\n\n3.Органы исполнительной власти субъектов Российской Федерации по соглашению с федеральными органами исполнительной власти могут передавать им осуществление части своих полномочий.\n\n4.Президент Российской Федерации и Правительство Российской Федерации обеспечивают в соответствии с Конституцией Российской Федерации осуществление полномочий федеральной государственной власти на всей территории Российской Федерации.\n\n5.Руководителем федерального государственного органа может быть гражданин Российской Федерации, достигший 30 лет, не имеющий гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Руководителю федерального государственного органа в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации.*","article_title":"Статья 78","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d573e2d7517d968da84a41b80e420c274b6e76486a4b1f5e17a7e7a197e734df"},{"code_id":"KONST_RF","article_number":"79","version_date":"1993-12-12","article_text":"Российская Федерация может участвовать в межгосударственных объединениях и передавать им часть своих полномочий в соответствии с международными договорами Российской Федерации, если это не влечет за собой ограничения прав и свобод человека и гражданина и не противоречит основам конституционного строя Российской Федерации. Решения межгосударственных органов, принятые на основании положений международных договоров Российской Федерации в их истолковании, противоречащем Конституции Российской Федерации, не подлежат исполнению в Российской Федерации.","article_title":"Статья 79","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"095df6da05942c6f174c0c5f6f60c7146456ca6cc0e5aa63bf6e4a618f0e3e31"},{"code_id":"KONST_RF","article_number":"8","version_date":"1993-12-12","article_text":"1.В Российской Федерации гарантируются единство экономического пространства, свободное перемещение товаров, услуг и финансовых средств, поддержка конкуренции, свобода экономической деятельности.\n\n2.В Российской Федерации признаются и защищаются равным образом частная, государственная, муниципальная и иные формы собственности.","article_title":"Статья 8","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8b7b598b6adec35ff639bd1f64cfe5273ddc0bd10e02156745c58f897b5be66"},{"code_id":"KONST_RF","article_number":"80","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации является главой государства.\n\n2.Президент Российской Федерации является гарантом Конституции Российской Федерации, прав и свобод человека и гражданина. В установленном Конституцией Российской Федерации порядке он принимает меры по охране суверенитета Российской Федерации, ее независимости и государственной целостности, поддерживает гражданский мир и согласие в стране, обеспечивает согласованное функционирование и взаимодействие органов, входящих в единую систему публичной власти.*\n\n3.Президент Российской Федерации в соответствии с Конституцией Российской Федерации и федеральными законами определяет основные направления внутренней и внешней политики государства.\n\n4.Президент Российской Федерации как глава государства представляет Российскую Федерацию внутри страны и в международных отношениях.","article_title":"Статья 80","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"49975cd74b7f2177640434d6a894372c8290e8374e905788436b83f8d930dca5"},{"code_id":"KONST_RF","article_number":"81","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации избирается сроком на шесть лет гражданами Российской Федерации на основе всеобщего равного и прямого избирательного права при тайном голосовании.\n\nРедакция части 1 приведена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 30 декабря 2008 г. № 6-ФКЗ«Об изменении срока полномочий Президента Российской Федерации и Государственной Думы», вступившим в силу со дня его официального опубликования 31 декабря 2008 г.(Российская газета, 2008, 31 декабря). Применяется в отношении Президента Российской Федерации, избранного после вступления в силу названного Закона.\n\n2.Президентом Российской Федерации может быть избран гражданин Российской Федерации не моложе 35 лет, постоянно проживающий в Российской Федерации не менее 25 лет, не имеющий и не имевший ранее гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Требование к кандидату на должность Президента Российской Федерации об отсутствии у него гражданства иностранного государства не распространяется на граждан Российской Федерации, ранее имевших гражданство государства, которое было принято или часть которого была принята в Российскую Федерацию в соответствии с федеральным конституционным законом, и постоянно проживавших на территории принятого в Российскую Федерацию государства или территории принятой в Российскую Федерацию части государства. Президенту Российской Федерации в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации.\n\n3.Одно и то же лицо не может занимать должность Президента Российской Федерации более двух сроков.\n\n31.Положение части 3 статьи 81 Конституции Российской Федерации, ограничивающее число сроков, в течение которых одно и то же лицо может занимать должность Президента Российской Федерации, применяется к лицу, занимавшему и (или) занимающему должность Президента Российской Федерации, без учета числа сроков, в течение которых оно занимало и (или) занимает эту должность на момент вступления в силу поправки к Конституции Российской Федерации, вносящей соответствующее ограничение, и не исключает для него возможность занимать должность Президента Российской Федерации в течение сроков, допустимых указанным положением.\n\n4.Порядок выборов Президента Российской Федерации определяется федеральным законом.","article_title":"Статья 81","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"892a6107ae96e11ee98d499fc55a1c4409b7df58fc048892751286b100ceb53b"},{"code_id":"KONST_RF","article_number":"82","version_date":"1993-12-12","article_text":"1.При вступлении в должность Президент Российской Федерации приносит народу следующую присягу:\n\n«Клянусь при осуществлении полномочий Президента Российской Федерации уважать и охранять права и свободы человека и гражданина, соблюдать и защищать Конституцию Российской Федерации, защищать суверенитет и независимость, безопасность и целостность государства, верно служить народу».\n\n2.Присяга приносится в торжественной обстановке в присутствии сенаторов Российской Федерации, депутатов Государственной Думы и судей Конституционного Суда Российской Федерации.*","article_title":"Статья 82","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"69b59ad2b260046fa31c989d6d000c573e76d815607a64841fecb0a6a280458f"},{"code_id":"KONST_RF","article_number":"83","version_date":"1993-12-12","article_text":"Президент Российской Федерации:\n\nа)назначает Председателя Правительства Российской Федерации, кандидатура которого утверждена Государственной Думой по представлению Президента Российской Федерации, и освобождает Председателя Правительства Российской Федерации от должности;*\n\nб)осуществляет общее руководство Правительством Российской Федерации; вправе председательствовать на заседаниях Правительства Российской Федерации;*\n\nб1)утверждает по предложению Председателя Правительства Российской Федерации структуру федеральных органов исполнительной власти, вносит в нее изменения; в структуре федеральных органов исполнительной власти определяет органы, руководство деятельностью которых осуществляет Президент Российской Федерации, и органы, руководство деятельностью которых осуществляет Правительство Российской Федерации. В случае если Председатель Правительства Российской Федерации освобожден Президентом Российской Федерации от должности, вновь назначенный Председатель Правительства Российской Федерации не представляет Президенту Российской Федерации предложения о структуре федеральных органов исполнительной власти;*\n\nв)принимает решение об отставке Правительства Российской Федерации;\n\nв1)принимает отставку Председателя Правительства Российской Федерации, заместителей Председателя Правительства Российской Федерации, федеральных министров, а также руководителей федеральных органов исполнительной власти, руководство деятельностью которых осуществляет Президент Российской Федерации;*\n\nг)представляет Государственной Думе кандидатуру для назначения на должность Председателя Центрального банка Российской Федерации; ставит перед Государственной Думой вопрос об освобождении от должности Председателя Центрального банка Российской Федерации;\n\nд)назначает на должность заместителей Председателя Правительства Российской Федерации и федеральных министров, кандидатуры которых утверждены Государственной Думой (за исключением федеральных министров, указанных в пункте «д1» настоящей статьи), и освобождает их от должности;*\n\nд1)назначает на должность после консультаций с Советом Федерации и освобождает от должности руководителей федеральных органов исполнительной власти (включая федеральных министров), ведающих вопросами обороны, безопасности государства, внутренних дел, юстиции, иностранных дел, предотвращения чрезвычайных ситуаций и ликвидации последствий стихийных бедствий, общественной безопасности;*\n\nе)представляет Совету Федерации кандидатуры для назначения на должность Председателя Конституционного Суда Российской Федерации, заместителя Председателя Конституционного Суда Российской Федерации и судей Конституционного Суда Российской Федерации, Председателя Верховного Суда Российской Федерации, заместителей Председателя Верховного Суда Российской Федерации и судей Верховного Суда Российской Федерации; назначает председателей, заместителей председателей и судей других федеральных судов;*\n\nе1)назначает на должность после консультаций с Советом Федерации и освобождает от должности Генерального прокурора Российской Федерации, заместителей Генерального прокурора Российской Федерации, прокуроров субъектов Российской Федерации, прокуроров военных и других специализированных прокуратур, приравненных к прокурорам субъектов Российской Федерации; назначает на должность и освобождает от должности иных прокуроров, для которых такой порядок назначения и освобождения от должности установлен федеральным законом;*\n\nе2)назначает и освобождает представителей Российской Федерации в Совете Федерации;\n\nСтатья 83 дополнена пунктом «е2» в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 21 июля 2014 г. № 11-ФКЗ «О Совете Федерации Федерального Собрания Российской Федерации», вступившим в силу со дня его официального опубликования 22 июля 2014 г. (Официальный интернет-портал правовой информации (www.pravo.gov.ru), 2014, 22 июля, № 0001201407220002).\n\nе3)вносит в Совет Федерации представление о прекращении в соответствии с федеральным конституционным законом полномочий Председателя Конституционного Суда Российской Федерации, заместителя Председателя Конституционного Суда Российской Федерации и судей Конституционного Суда Российской Федерации, Председателя Верховного Суда Российской Федерации, заместителей Председателя Верховного Суда Российской Федерации и судей Верховного Суда Российской Федерации, председателей, заместителей председателей и судей кассационных и апелляционных судов в случае совершения ими поступка, порочащего честь и достоинство судьи, а также в иных предусмотренных федеральным конституционным законом случаях, свидетельствующих о невозможности осуществления судьей своих полномочий;*\n\nе4)представляет Совету Федерации кандидатуры для назначения на должность Председателя Счетной палаты и половины от общего числа аудиторов Счетной палаты; представляет Государственной Думе кандидатуры для назначения на должность заместителя Председателя Счетной палаты и половины от общего числа аудиторов Счетной палаты;*\n\nе5)формирует Государственный Совет Российской Федерации в целях обеспечения согласованного функционирования и взаимодействия органов публичной власти, определения основных направлений внутренней и внешней политики Российской Федерации и приоритетных направлений социально-экономического развития государства; статус Государственного Совета Российской Федерации определяется федеральным законом;*\n\nж)формирует Совет Безопасности Российской Федерации в целях содействия главе государства в реализации его полномочий по вопросам обеспечения национальных интересов и безопасности личности, общества и государства, а также поддержания гражданского мира и согласия в стране, охраны суверенитета Российской Федерации, ее независимости и государственной целостности, предотвращения внутренних и внешних угроз; возглавляет Совет Безопасности Российской Федерации. Статус Совета Безопасности Российской Федерации определяется федеральным законом;*\n\nз)утверждает военную доктрину Российской Федерации;\n\nи)формирует Администрацию Президента Российской Федерации в целях обеспечения реализации своих полномочий;*\n\nк)назначает и освобождает полномочных представителей Президента Российской Федерации;\n\nл)назначает и освобождает высшее командование Вооруженных Сил Российской Федерации;\n\nм)назначает и отзывает после консультаций с соответствующими комитетами или комиссиями палат Федерального Собрания дипломатических представителей Российской Федерации в иностранных государствах и международных организациях.","article_title":"Статья 83","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5432e1b08cb5a304b27f90dbc24d6a349010c88221ceaaef936b8f153b1e708c"},{"code_id":"KONST_RF","article_number":"84","version_date":"1993-12-12","article_text":"Президент Российской Федерации:\n\nа)назначает выборы Государственной Думы в соответствии с Конституцией Российской Федерации и федеральным законом;\n\nб)распускает Государственную Думу в случаях и порядке, предусмотренных Конституцией Российской Федерации;\n\nв)назначает референдум в порядке, установленном федеральным конституционным законом;\n\nг)вносит законопроекты в Государственную Думу;\n\nд)подписывает и обнародует федеральные законы;\n\nе)обращается к Федеральному Собранию с ежегодными посланиями о положении в стране, об основных направлениях внутренней и внешней политики государства.","article_title":"Статья 84","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd47dfe61b942c65de703a3a17725ebd345791316932f45bd8bccfcdc3b80bbe"},{"code_id":"KONST_RF","article_number":"85","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации может использовать согласительные процедуры для разрешения разногласий между органами государственной власти Российской Федерации и органами государственной власти субъектов Российской Федерации, а также между органами государственной власти субъектов Российской Федерации. В случае недостижения согласованного решения он может передать разрешение спора на рассмотрение соответствующего суда.\n\n2.Президент Российской Федерации вправе приостанавливать действие актов органов исполнительной власти субъектов Российской Федерации в случае противоречия этих актов Конституции Российской Федерации и федеральным законам, международным обязательствам Российской Федерации или нарушения прав и свобод человека и гражданина до решения этого вопроса соответствующим судом.","article_title":"Статья 85","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cec22e46f9daf7d503f835bec3d9f0ac9bb17472f72bd2267dab692a46089704"},{"code_id":"KONST_RF","article_number":"86","version_date":"1993-12-12","article_text":"Президент Российской Федерации:\n\nа)осуществляет руководство внешней политикой Российской Федерации;\n\nб)ведет переговоры и подписывает международные договоры Российской Федерации;\n\nв)подписывает ратификационные грамоты;\n\nг)принимает верительные и отзывные грамоты аккредитуемых при нем дипломатических представителей.","article_title":"Статья 86","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"68884727b05857c5f58ee7bf071d9ab4bcb9275b64a306c976bca3481d960ad7"},{"code_id":"KONST_RF","article_number":"87","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации является Верховным Главнокомандующим Вооруженными Силами Российской Федерации.\n\n2.В случае агрессии против Российской Федерации или непосредственной угрозы агрессии Президент Российской Федерации вводит на территории Российской Федерации или в отдельных ее местностях военное положение с незамедлительным сообщением об этом Совету Федерации и Государственной Думе.\n\n3.Режим военного положения определяется федеральным конституционным законом.","article_title":"Статья 87","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a101f3775f989706c3192968201b8a95f2e1d17af9d27e9827c448f6f6da63e8"},{"code_id":"KONST_RF","article_number":"88","version_date":"1993-12-12","article_text":"Президент Российской Федерации при обстоятельствах и в порядке, предусмотренных федеральным конституционным законом, вводит на территории Российской Федерации или в отдельных ее местностях чрезвычайное положение с незамедлительным сообщением об этом Совету Федерации и Государственной Думе.","article_title":"Статья 88","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"590cab13b9bac7cb5ca95bd6cd3ce913b12aafe207fb3b93d283b7a491f2e4fb"},{"code_id":"KONST_RF","article_number":"89","version_date":"1993-12-12","article_text":"Президент Российской Федерации:\n\nа)решает вопросы гражданства Российской Федерации и предоставления политического убежища;\n\nб)награждает государственными наградами Российской Федерации, присваивает почетные звания Российской Федерации, высшие воинские и высшие специальные звания;\n\nв)осуществляет помилование.","article_title":"Статья 89","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7d5908353bb7c35e7aaeadabb10d0e0228cb7dae1541be31febc0d77c907f1ec"},{"code_id":"KONST_RF","article_number":"9","version_date":"1993-12-12","article_text":"1.Земля и другие природные ресурсы используются и охраняются в Российской Федерации как основа жизни и деятельности народов, проживающих на соответствующей территории.\n\n2.Земля и другие природные ресурсы могут находиться в частной, государственной, муниципальной и иных формах собственности.","article_title":"Статья 9","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"056bd137c38bf8a625aab3218ac484801cd102f9d10a2d4d3399b56a9fa52908"},{"code_id":"KONST_RF","article_number":"90","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации издает указы и распоряжения.\n\n2.Указы и распоряжения Президента Российской Федерации обязательны для исполнения на всей территории Российской Федерации.\n\n3.Указы и распоряжения Президента Российской Федерации не должны противоречить Конституции Российской Федерации и федеральным законам.","article_title":"Статья 90","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"375b1e9028e78d99474fbbd745a76627b4a67087fb305f5557394d40ac39a9d1"},{"code_id":"KONST_RF","article_number":"91","version_date":"1993-12-12","article_text":"Президент Российской Федерации обладает неприкосновенностью.","article_title":"Статья 91","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1e90750ca3811401df948cba2f60a9a255cbb97217213e7a543d48875d41b9f1"},{"code_id":"KONST_RF","article_number":"92","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации приступает к исполнению полномочий с момента принесения им присяги и прекращает их исполнение с истечением срока его пребывания в должности с момента принесения присяги вновь избранным Президентом Российской Федерации.\n\n2.Президент Российской Федерации прекращает исполнение полномочий досрочно в случае его отставки, стойкой неспособности по состоянию здоровья осуществлять принадлежащие ему полномочия или отрешения от должности. При этом выборы Президента Российской Федерации должны состояться не позднее трех месяцев с момента досрочного прекращения исполнения полномочий.\n\n3.Во всех случаях, когда Президент Российской Федерации не в состоянии выполнять свои обязанности, их временно исполняет Председатель Правительства Российской Федерации. Исполняющий обязанности Президента Российской Федерации не имеет права распускать Государственную Думу, назначать референдум, а также вносить предложения о поправках и пересмотре положений Конституции Российской Федерации.","article_title":"Статья 92","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"204ac567f6569207cc855cc4af0ce7fb4532f0126ecd37d147c60ddfa5674dc3"},{"code_id":"KONST_RF","article_number":"93","version_date":"1993-12-12","article_text":"1.Президент Российской Федерации может быть отрешен от должности, а Президент Российской Федерации, прекративший исполнение своих полномочий, лишен неприкосновенности Советом Федерации только на основании выдвинутого Государственной Думой обвинения в государственной измене или совершении иного тяжкого преступления, подтвержденного заключением Верховного Суда Российской Федерации о наличии в действиях Президента Российской Федерации, как действующего, так и прекратившего исполнение своих полномочий, признаков преступления и заключением Конституционного Суда Российской Федерации о соблюдении установленного порядка выдвижения обвинения.\n\n2.Решение Государственной Думы о выдвижении обвинения и решение Совета Федерации об отрешении Президента Российской Федерации от должности, о лишении неприкосновенности Президента Российской Федерации, прекратившего исполнение своих полномочий, должны быть приняты двумя третями голосов от общего числа соответственно сенаторов Российской Федерации и депутатов Государственной Думы по инициативе не менее одной трети депутатов Государственной Думы и при наличии заключения специальной комиссии, образованной Государственной Думой.\n\n3.Решение Совета Федерации об отрешении Президента Российской Федерации от должности, о лишении неприкосновенности Президента Российской Федерации, прекратившего исполнение своих полномочий, должно быть принято не позднее чем в трехмесячный срок после выдвижения Государственной Думой обвинения против Президента Российской Федерации. Если в этот срок решение Совета Федерации не будет принято, обвинение против Президента Российской Федерации, Президента Российской Федерации, прекратившего исполнение своих полномочий, считается отклоненным.","article_title":"Статья 93","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4de0fb6edc9797770e74ca59903b9c0d65fc4534b569ae67da5728ae7b0b6775"},{"code_id":"KONST_RF","article_number":"94","version_date":"1993-12-12","article_text":"Федеральное Собрание — парламент Российской Федерации — является представительным и законодательным органом Российской Федерации.","article_title":"Статья 94","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d9dcdf0febfa4ee05517d2098ae781e59fe69c828444a98063e1fc38eb234a77"},{"code_id":"KONST_RF","article_number":"95","version_date":"1993-12-12","article_text":"1.Федеральное Собрание состоит из двух палат — Совета Федерации и Государственной Думы.\n\n2.Совет Федерации состоит из сенаторов Российской Федерации.В Совет Федерации входят:\n\nа)по два представителя от каждого субъекта Российской Федерации: по одному от законодательного (представительного) и исполнительного органов государственной власти — на срок полномочий соответствующего органа;\n\nб)Президент Российской Федерации, прекративший исполнение своих полномочий в связи с истечением срока его пребывания в должности или досрочно в случае его отставки, — пожизненно. Президент Российской Федерации, прекративший исполнение своих полномочий в связи с истечением срока его пребывания в должности или досрочно в случае его отставки, вправе отказаться от полномочий сенатора Российской Федерации;\n\nв)не более 30 представителей Российской Федерации, назначаемых Президентом Российской Федерации, из которых не более семи могут быть назначены пожизненно.\n\n3.Общее число сенаторов Российской Федерации определяется исходя из числа представителей от субъектов Российской Федерации, перечисленных в статье 65 Конституции Российской Федерации, и числа лиц, осуществляющих полномочия сенаторов Российской Федерации, указанных в пунктах «б» и «в» части 2 настоящей статьи.\n\n4.Сенатором Российской Федерации может быть гражданин Российской Федерации, достигший 30 лет, постоянно проживающий в Российской Федерации, не имеющий гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Сенаторам Российской Федерации в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации.\n\n5.Представителями Российской Федерации в Совете Федерации, осуществляющими полномочия сенаторов Российской Федерации пожизненно, могут быть назначены граждане, имеющие выдающиеся заслуги перед страной в сфере государственной и общественной деятельности.\n\n6.Представители Российской Федерации в Совете Федерации, за исключением представителей Российской Федерации, осуществляющих полномочия сенаторов Российской Федерации пожизненно, назначаются сроком на шесть лет.\n\n7.Государственная Дума состоит из 450 депутатов.","article_title":"Статья 95","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6f6913855b58760a20d995d9706e151e85e08475b6ea13429adfdf154a199647"},{"code_id":"KONST_RF","article_number":"96","version_date":"1993-12-12","article_text":"1.Государственная Дума избирается сроком напять лет.\n\nРедакция части 1 приведена в соответствии с Законом Российской Федерации о поправке к Конституции Российской Федерации от 30 декабря 2008 г. № 6-ФКЗ«Об изменении срока полномочий Президента Российской Федерации и Государственной Думы», вступившим в силу со дня его официального опубликования 31 декабря 2008 г.(Российская газета, 2008, 31 декабря). Применяется в отношении Государственной Думы, избранной после вступления в силу названного Закона.\n\n2.Порядок формирования Совета Федерации и порядок выборов депутатов Государственной Думы устанавливаются федеральными законами.","article_title":"Статья 96","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d25b55e735482fff69622e08ecd7cdf2f1127f6440eda0eabe29a4bfb64d05ed"},{"code_id":"KONST_RF","article_number":"97","version_date":"1993-12-12","article_text":"1.Депутатом Государственной Думы может быть избран гражданин Российской Федерации, достигший 21 года и имеющий право участвовать в выборах, постоянно проживающий в Российской Федерации, не имеющий гражданства иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. Депутатам Государственной Думы в порядке, установленном федеральным законом, запрещается открывать и иметь счета (вклады), хранить наличные денежные средства и ценности в иностранных банках, расположенных за пределами территории Российской Федерации.*\n\n2.Одно и то же лицо не может одновременно являться сенатором Российской Федерации и депутатом Государственной Думы. Депутат Государственной Думы не может быть депутатом иных представительных органов государственной власти и органов местного самоуправления.*\n\n3.Депутаты Государственной Думы работают на профессиональной постоянной основе. Депутаты Государственной Думы не могут находиться на государственной службе, заниматься другой оплачиваемой деятельностью, кроме преподавательской, научной и иной творческой деятельности.","article_title":"Статья 97","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a9976d1c69a10710f544f0f5766d46e027214ef7f04b3e762a0e4d76b3046208"},{"code_id":"KONST_RF","article_number":"98","version_date":"1993-12-12","article_text":"1.Сенаторы Российской Федерации и депутаты Государственной Думы обладают неприкосновенностью в течение всего срока их полномочий. Они не могут быть задержаны, арестованы, подвергнуты обыску, кроме случаев задержания на месте преступления, а также подвергнуты личному досмотру, за исключением случаев, когда это предусмотрено федеральным законом для обеспечения безопасности других людей.*\n\n2.Вопрос о лишении неприкосновенности решается по представлению Генерального прокурора Российской Федерации соответствующей палатой Федерального Собрания.","article_title":"Статья 98","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93a2c974d58bc7e0ed22f2317498743fcf9fb44206b53be0b02dc224ef185ef6"},{"code_id":"KONST_RF","article_number":"99","version_date":"1993-12-12","article_text":"1.Федеральное Собрание является постоянно действующим органом.\n\n2.Государственная Дума собирается на первое заседание на тридцатый день после избрания. Президент Российской Федерации может созвать заседание Государственной Думы ранее этого срока.\n\n3.Первое заседание Государственной Думы открывает старейший по возрасту депутат.\n\n4.С момента начала работы Государственной Думы нового созыва полномочия Государственной Думы прежнего созыва прекращаются.","article_title":"Статья 99","amendment_eo_number":null,"amendment_date":"1993-12-12","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c6e46a71036bcbee5ca4360399b2492003bd4e56c817928961a390e16fa79118"},{"code_id":"NK_RF","article_number":"1","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.07.2006 № 137-ФЗ, от 11.06.2021 № 199-ФЗ)\n\n1) виды налогов и сборов, взимаемых в Российской Федерации; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n2) основания возникновения (изменения, прекращения) и порядок исполнения обязанностей по уплате налогов и сборов; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n3) принципы установления, введения в действие и прекращения действия ранее введенных налогов субъектов Российской Федерации и местных налогов; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2006 № 137-ФЗ)\n\n4) права и обязанности налогоплательщиков, налоговых органов и других участников отношений, регулируемых законодательством о налогах и сборах; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n5) формы и методы налогового контроля; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n6) ответственность за совершение налоговых правонарушений; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n7) порядок обжалования актов налоговых органов и действий (бездействия) их должностных лиц. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nПравоотношения, возникающие в ходе проведения указанных экспериментов, регулируются законодательством о налогах и сборах с учетом особенностей, установленных федеральными законами о проведении экспериментов.\n\nВ период проведения эксперимента, но не позднее чем за шесть месяцев до его окончания Правительство Российской Федерации представляет в Государственную Думу Федерального Собрания Российской Федерации отчет об эффективности (неэффективности) проведенного эксперимента, а также предложения о его продлении, об установлении настоящим Кодексом соответствующего налога, сбора, специального налогового режима либо о прекращении такого эксперимента.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2018 № 425-ФЗ)","article_title":"Статья 1. Законодательство Российской Федерации о налогах и сборах, законодательство субъектов Российской Федерации о налогах и сборах, нормативные правовые акты представительных органов муниципальных образований о налогах и сборах, нормативные правовые акты представительного органа федеральной территории \"Сириус\" о местных налогах и сборах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50fa0b25a90ebe6993519d6a3b33cfab47e8ad1739787cc32db5ddbaf5f2f338"},{"code_id":"NK_RF","article_number":"10","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n1. Порядок привлечения к ответственности и производство по делам о налоговых правонарушениях осуществляются в порядке, установленном главами 14, 15 настоящего Кодекса.\n\n2. Производство по делам о нарушениях законодательства о налогах и сборах, содержащих признаки административного правонарушения или преступления, ведется в порядке, установленном соответственно законодательством Российской Федерации об административных правонарушениях и уголовно-процессуальным законодательством Российской Федерации.","article_title":"Статья 10. Порядок производства по делам о нарушениях законодательства о налогах и сборах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"489778748cd8c16527f27a4108543dcad2df7052b28cf0f7630e85ae0753bab3"},{"code_id":"NK_RF","article_number":"100","version_date":"2000-07-31","article_text":"1. По результатам выездной налоговой проверки в течение двух месяцев со дня составления справки о проведенной выездной налоговой проверке уполномоченными должностными лицами налоговых органов должен быть составлен в установленной форме акт налоговой проверки.\n\nВ случае выявления нарушений законодательства о налогах и сборах в ходе проведения камеральной налоговой проверки должностными лицами налогового органа, проводящими указанную проверку, должен быть составлен акт налоговой проверки по установленной форме в течение 10 дней после окончания камеральной налоговой проверки.\n\nПо результатам выездной налоговой проверки консолидированной группы налогоплательщиков в течение трех месяцев со дня составления справки о проведенной выездной налоговой проверке уполномоченными должностными лицами налоговых органов должен быть составлен в установленной форме акт налоговой проверки. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n2. Акт налоговой проверки подписывается лицами, проводившими соответствующую проверку, и лицом, в отношении которого проводилась эта проверка (его представителем). При проведении налоговой проверки консолидированной группы налогоплательщиков акт налоговой проверки подписывается лицами, проводившими соответствующую проверку, и ответственным участником этой группы (его представителем).\n\nОб отказе лица, в отношении которого проводилась налоговая проверка, или его представителя (ответственного участника консолидированной группы налогоплательщиков) подписать акт делается соответствующая запись в акте налоговой проверки.\n\n(Пункт в редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\n3. В акте налоговой проверки указываются:\n\n1) дата акта налоговой проверки. Под указанной датой понимается дата подписания акта лицами, проводившими эту проверку;\n\n2) полное и сокращенное наименования либо фамилия, имя, отчество проверяемого лица (участников консолидированной группы налогоплательщиков). В случае проведения проверки организации по месту нахождения ее обособленного подразделения помимо наименования организации указываются полное и сокращенное наименования проверяемого обособленного подразделения и место его нахождения; (В редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\n3) фамилии, имена, отчества лиц, проводивших проверку, их должности с указанием наименования налогового органа, который они представляют;\n\n4) дата и номер решения руководителя (заместителя руководителя) налогового органа о проведении выездной налоговой проверки (для выездной налоговой проверки);\n\n5) дата представления в налоговый орган налоговой декларации (расчета) и иных документов (для камеральной налоговой проверки); (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n6) перечень документов, представленных проверяемым лицом в ходе налоговой проверки;\n\n7) период, за который проведена проверка;\n\n8) наименование налога, в отношении которого проводилась налоговая проверка;\n\n9) даты начала и окончания налоговой проверки;\n\n10) адрес места нахождения организации (участников консолидированной группы налогоплательщиков) или места жительства физического лица; (В редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\n11) сведения о мероприятиях налогового контроля, проведенных при осуществлении налоговой проверки;\n\n12) документально подтвержденные факты нарушений законодательства о налогах и сборах, выявленные в ходе проверки, или запись об отсутствии таковых;\n\n13) выводы и предложения проверяющих по устранению выявленных нарушений и ссылки на статьи настоящего Кодекса в случае, если настоящим Кодексом предусмотрена ответственность за данные нарушения законодательства о налогах и сборах.\n\n4. Форма и требования к составлению акта налого\n\nвой проверки устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если лицо, в отношении которого проводилась проверка, или его представитель уклоняются от получения акта налоговой проверки, этот факт отражается в акте налоговой проверки, и акт налоговой проверки направляется по почте заказным письмом по месту нахождения организации (обособленного подразделения) или месту жительства физического лица. В случае направления акта налоговой проверки по почте заказным письмом датой вручения этого акта считается шестой день считая с даты отправки заказного письма.\n\nПри проведении налоговой проверки консолидированной группы налогоплательщиков акт налоговой проверки в течение 10 дней с даты этого акта вручается ответственному участнику консолидированной группы налогоплательщиков в порядке, установленном настоящим пунктом. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\nАкт налоговой проверки направляется иностранной организации (за исключением международной организации, дипломатического представительства, иностранного лица, подлежащего постановке на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса), не осуществляющей деятельность на территории Российской Федерации через обособленное подразделение, по почте заказным письмом по адресу, содержащемуся в Едином государственном реестре налогоплательщиков. Датой вручения этого акта считается двадцатый день, считая с даты отправки заказного письма. (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции  федеральных законов от 03.07.2016 № 244-ФЗ, от 29.05.2024 № 100-ФЗ)\n\nПисьменные возражения по акту налоговой проверки консолидированной группы налогоплательщиков представляются ответственным участником этой группы в течение 30 дней со дня получения указанного акта. При этом ответственный участник консолидированной группы налогоплательщиков вправе приложить к письменным возражениям или в согласованный срок передать в налоговый орган документы (их заверенные копии), подтверждающие обоснованность своих возражений. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 100. Оформление результатов налоговой проверки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1219473fa250174c6de2a2738a71c47b7308941d72b72a1ed4997ab594edfcbf"},{"code_id":"NK_RF","article_number":"100.1","version_date":"2000-07-31","article_text":"1. Дела о выявленных в ходе камеральной или выездной налоговой проверки налоговых правонарушениях рассматриваются в порядке, предусмотренном статьей 101 настоящего Кодекса.\n\n2. Дела о выявленных в ходе иных мероприятий налогового контроля налоговых правонарушениях (за исключением правонарушений, предусмотренных статьями 120, 122 и 123 настоящего Кодекса) рассматриваются в порядке, предусмотренном статьей 1014 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 100.1. Порядок рассмотрения дел о налоговых правонарушениях","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc7c9ee6bee0835ef8beb4e736dab3b9780de8a0ee62f3e97c7adb613154a82d"},{"code_id":"NK_RF","article_number":"101","version_date":"2000-07-31","article_text":"1. Акт налоговой проверки, другие материалы налоговой проверки, в ходе которых были выявлены нарушения законодательства о налогах и сборах, а также представленные проверяемым лицом (его представителем) письменные возражения по указанному акту должны быть рассмотрены руководителем (заместителем руководителя) налогового органа, проводившего налоговую проверку. По результатам их рассмотрения руководителем (заместителем руководителя) налогового органа в течение 10 дней со дня истечения срока, указанного в пункте 6 статьи 100 настоящего Кодекса, принимается одно из решений, предусмотренных пунктом 7 настоящей статьи, или решение о проведении дополнительных мероприятий налогового контроля. Срок рассмотрения материалов налоговой проверки и вынесения соответствующего решения может быть продлен, но не более чем на один месяц.\n\nВ случае принятия решения о проведении дополнительных мероприятий налогового контроля акт налоговой проверки, другие материалы налоговой проверки и дополнительных мероприятий налогового контроля, а также представленные проверяемым лицом (его представителем) письменные возражения должны быть также рассмотрены руководителем (заместителем руководителя) налогового органа, проводившего налоговую проверку. По результатам их рассмотрения руководителем (заместителем руководителя) налогового органа в течение 10 дней со дня истечения срока, указанного в пункте 62 настоящей статьи, принимается одно из решений, предусмотренных пунктом 7 настоящей статьи. (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\nЛицо, в отношении которого проводилась налоговая проверка, вправе участвовать в процессе рассмотрения материалов указанной проверки лично и (или) через своего представителя. При проведении налоговой проверки консолидированной группы налогоплательщиков в процессе рассмотрения материалов налоговой проверки вправе участвовать представители ответственного участника этой группы, других участников такой группы. (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 16.11.2011 № 321-ФЗ; от 23.07.2013 № 248-ФЗ; от 01.05.2016 № 130-ФЗ)\n\nЛицо, в отношении которого проводилась налоговая проверка (его представитель), вправе до рассмотрения материалов указанной проверки ознакомиться с материалами налоговой проверки и дополнительных мероприятий налогового контроля в течение срока, предусмотренного для представления письменных возражений пунктом 6 статьи 100 настоящего Кодекса и пунктом 62 настоящей статьи. Налоговый орган обязан обеспечить лицу, в отношении которого проводилась налоговая проверка (его представителю), возможность ознакомиться с материалами налоговой проверки и дополнительных мероприятий налогового контроля на территории налогового органа не позднее двух дней со дня подачи таким лицом соответствующего заявления. Ознакомление с такими материалами осуществляется путем их визуального осмотра, изготовления выписок, снятия копий. По окончании ознакомления составляется протокол в соответствии со статьей 99 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 01.05.2016 № 130-ФЗ) (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\nНеявка лица, в отношении которого проводилась налоговая проверка (его представителя), извещенного надлежащим образом о времени и месте рассмотрения материалов налоговой проверки, не является препятствием для рассмотрения материалов налоговой проверки, за исключением тех случаев, когда участие этого лица будет признано руководителем (заместителем руководителя) налогового органа обязательным для рассмотрения этих материалов.\n\nОбязанность по извещению участников консолидированной группы налогоплательщиков о времени и месте рассмотрения материалов налоговой проверки лежит на ответственном участнике этой группы. Ненадлежащее исполнение указанной обязанности ответственным участником этой группы не является основанием для отложения рассмотрения материалов налоговой проверки. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\nНалоговый орган обязан известить участника консолидированной группы налогоплательщиков о времени и месте рассмотрения материалов налоговой проверки, если в акте налоговой проверки по консолидированной группе налогоплательщиков имеется предложение о привлечении этого участника к ответственности за совершение налогового правонарушения. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n1) объявить, кто рассматривает дело и материалы какой налоговой проверки подлежат рассмотрению;\n\n2) установить факт явки лиц, приглашенных для участия в рассмотрении. В случае неявки этих лиц руководитель (заместитель руководителя) налогового органа выясняет, извещены ли участники производства по делу в установленном порядке, и принимает решение о рассмотрении материалов налоговой проверки в отсутствие указанных лиц либо об отложении указанного рассмотрения;\n\n3) в случае участия представителя лица, в отношении которого проводилась налоговая проверка, проверить полномочия этого представителя;\n\n4) разъяснить лицам, участвующим в процедуре рассмотрения, их права и обязанности;\n\n5) вынести решение об отложении рассмотрения материалов налоговой проверки в случае неявки лица, участие которого необходимо для рассмотрения.\n\nПри рассмотрении материалов налоговой проверки исследуются представленные до рассмотрения материалов налоговой проверки доказательства, с которыми лицу, в отношении которого проводилась проверка, была предоставлена возможность ознакомиться, в том числе документы, ранее истребованные у лица, в отношении которого проводилась налоговая проверка (включая участников консолидированной группы налогоплательщиков), документы, представленные в налоговые органы при проведении камеральных или выездных налоговых проверок данных лиц, и иные документы, имеющиеся у налогового органа. Не допускается использование доказательств, полученных с нарушением настоящего Кодекса, а также доказательств, полученных из специальной декларации, представленной в соответствии с Федеральным законом \"О добровольном декларировании физическими лицами активов и счетов (вкладов) в банках и о внесении изменений в отдельные законодательные акты Российской Федерации\", и (или) прилагаемых к ней документов и (или) сведений. Если документы (информация) о деятельности налогоплательщика (консолидированной группы налогоплательщиков) были представлены в налоговый орган с нарушением сроков, установленных настоящим Кодексом, полученные налоговым органом документы (информация) не будут считаться полученными с нарушением настоящего Кодекса. В ходе рассмотрения материалов налоговой проверки может быть принято решение о привлечении в случае необходимости к участию в этом рассмотрении свидетеля, эксперта, специалиста. (В редакции федеральных законов от 16.11.2011 № 321-ФЗ; от 08.06.2015 № 150-ФЗ; от 03.08.2018 № 302-ФЗ)\n\nПри рассмотрении материалов налоговой проверки ведется протокол. (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\n1) устанавливает, совершало ли лицо, в отношении которого был составлен акт налоговой проверки (участник (участники) консолидированной группы налогоплательщиков), нарушение законодательства о налогах и сборах; (В редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\n2) устанавливает, образуют ли выявленные нарушения состав налогового правонарушения;\n\n3) устанавливает, имеются ли основания для привлечения лица к ответственности за совершение налогового правонарушения;\n\n4) выявляет обстоятельства, исключающие вину лица в совершении налогового правонарушения, либо обстоятельства, смягчающие или отягчающие ответственность за совершение налогового правонарушения.\n\nВ решении о проведении дополнительных мероприятий налогового контроля излагаются обстоятельства, вызвавшие необходимость проведения таких дополнительных мероприятий, указываются срок и конкретная форма их проведения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nВ качестве дополнительных мероприятий налогового контроля может проводиться истребование документов в соответствии со статьями 93 и 931 настоящего Кодекса, допрос свидетеля, проведение экспертизы.\n\nДополнение к акту налоговой проверки должно быть составлено и подписано должностными лицами налогового органа, проводящими дополнительные мероприятия налогового контроля, в течение пятнадцати дней со дня окончания таких мероприятий.\n\nДополнение к акту налоговой проверки с приложением материалов, полученных в результате проведения дополнительных мероприятий налогового контроля, в течение пяти дней с даты этого дополнения должно быть вручено лицу, в отношении которого проводилась налоговая проверка (его представителю), под расписку или передано иным способом, свидетельствующим о дате его получения указанным лицом (его представителем), если иное не предусмотрено настоящим пунктом.\n\nПри проведении дополнительных мероприятий налогового контроля в отношении консолидированной группы налогоплательщиков дополнение к акту налоговой проверки в течение десяти дней с даты этого дополнения вручается ответственному участнику консолидированной группы налогоплательщиков в порядке, установленном настоящим пунктом.\n\nДополнение к акту налоговой проверки направляется иностранной организации (за исключением международной организации, дипломатического представительства, иностранного лица, подлежащего постановке на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса), не осуществляющей деятельность на территории Российской Федерации через обособленное подразделение, по почте заказным письмом по адресу, содержащемуся в Едином государственном реестре налогоплательщиков. Датой вручения этого дополнения к акту налоговой проверки считается двадцатый день, считая с даты отправки заказного письма. (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\nПри этом документы, полученные от лица, в отношении которого проводилась налоговая проверка, к дополнению к акту налоговой проверки не прилагаются.\n\nВ случае, если лицо, в отношении которого проводилась налоговая проверка (его представитель), уклоняется от получения дополнения к акту налоговой проверки, такой факт отражается в дополнении к акту налоговой проверки. В этом случае дополнение к акту налоговой проверки направляется по почте заказным письмом по месту нахождения организации (обособленного подразделения) или месту жительства физического лица и считается полученным на шестой день с даты отправки заказного письма.\n\n(Дополнение пунктом - Федеральный закон от 01.05.2016 № 130-ФЗ) (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n1) о привлечении к ответственности за совершение налогового правонарушения. При проверке консолидированной группы налогоплательщиков в указанном решении может содержаться указание о привлечении к ответственности одного или нескольких участников этой группы; (В редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\n2) об отказе в привлечении к ответственности за совершение налогового правонарушения.\n\nВ решении об отказе в привлечении к ответственности за совершение налогового правонарушения излагаются обстоятельст\n\nва, послужившие основанием для такого отказа. В решении об отказе в привлечении к ответственности за налоговые правонарушения может быть указан размер недоимки, если эта недоимка была выявлена в ходе проверки. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nВ решении о привлечении к ответственности за совершение налогового правонарушения либо в решении об отказе в привлечении к ответственности за совершение налогового правонарушения указываются срок, в течение которого лицо, в отношении которого вынесено решение, вправе обжаловать указанное решение, порядок обжалования решения в вышестоящий налоговый орган, а также наименование органа, его место нахождения, другие необходимые сведения. (В редакции Федерального закона от 02.07.2013 № 153-ФЗ)\n\nВ случае обнаружения в ходе налоговой проверки суммы налога, излишне возмещенной на основании решения налогового органа, в решении о привлечении к ответственности за совершение налогового правонарушения либо в решении об отказе в привлечении к ответственности за совершение налогового правонарушения указанная сумма признается недоимкой. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 248-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nВ случае, если размер недоимки, выявленный в результате налоговой проверки, позволяет предполагать факт совершения нарушения законодательства о налогах и сборах, содержащего признаки преступления, в решении о привлечении к ответственности за совершение налогового правонарушения либо в решении об отказе в привлечении к ответственности за совершение налогового правонарушения должно содержаться предупреждение лица, в отношении которого вынесено соответствующее решение, об обязанности налогового органа в случае неуплаты этим лицом суммы недоимки в полном объеме направить в установленный в соответствии с пунктом 3 статьи 32 настоящего Кодекса срок материалы в следственные органы для решения вопроса о возбуждении уголовного дела. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nВ случае подачи апелляционной жалобы на решение налогового органа указанное решение вступает в силу в порядке, предусмотренном статьей 1012 настоящего Кодекса. (В редакции Федерального закона от 02.07.2013 № 153-ФЗ)\n\nЛицо, в отношении которого вынесено соответствующее решение, вправе исполнить решение полностью или в части до вступления его в силу. При этом подача апелляционной жалобы не лишает это лицо права исполнить не вступившее в силу решение полностью или в части.\n\nРуководитель (заместитель руководителя) налогового органа вправе принять решение об отмене обеспечительных мер или решение о замене обеспечительных мер в случаях, предусмотренных настоящим пунктом и пунктом 11 настоящей статьи. Решение об отмене (замене) обеспечительных мер вступает в силу со дня его вынесения. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nОбеспечительными мерами могут быть:\n\n1) запрет на отчуждение (передачу в залог) имущества налогоплательщика без согласия налогового органа. Предусмотренный настоящим подпунктом запрет на отчуждение (передачу в залог) производится последовательно в отношении:\n\nнедвижимого имущества, в том числе не участвующего в производстве продукции (работ, услуг);\n\nтранспортных средств, ценных бумаг, предметов дизайна служебных помещений;\n\nиного имущества, за исключением готовой продукции, сырья и материалов;\n\nготовой продукции, сырья и материалов.\n\nПри этом запрет на отчуждение (передачу в залог) имущества каждой последующей группы применяется в случае, если совокупная стоимость имущества из предыдущих групп, определяемая по данным бухгалтерского учета, меньше общей суммы недоимки, пеней и штрафов, подлежащей уплате на основании решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения;\n\n2) приостановление операций по счетам в банке, по счетам цифрового рубля в порядке, установленном статьей 76 настоящего Кодекса. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПриостановление операций по счетам в банке, по счетам цифрового рубля в порядке принятия обеспечительных мер может применяться только после наложения запрета на отчуждение (передачу в залог) имущества и в случае, если совокупная стоимость такого имущества по данным бухгалтерского учета меньше общей суммы недоимки, пеней и штрафов, подлежащей уплате на основании решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПриостановление операций по счетам в банке, по счетам цифрового рубля допускается в отношении разницы между общей суммой недоимки, пеней и штрафов, указанной в решении о привлечении к ответственности за совершение налогового правонарушения или решении об отказе в привлечении к ответственности за совершение налогового правонарушения, и стоимостью имущества, не подлежащего отчуждению (передаче в залог) в соответствии с подпунктом 1 настоящего пункта. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ) (Утратил силу - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n1) банковскую гарантию, отвечающую требованиям, установленным статьей 741 настоящего Кодекса, и подтверждающую, что гарант обязывается перед налоговыми органами уплатить в соответствии с условиями даваемого гарантом обязательства указанную в решении о привлечении к ответственности за совершение налогового правонарушения или в решении об отказе в привлечении к ответственности за совершение налогового правонарушения сумму задолженности в случае неуплаты этой суммы принципалом в установленный срок, по представленному налоговым органом гаранту в письменной форме или электронной форме по телекоммуникационным каналам связи требованию об уплате этой суммы; (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n2) залог ценных бумаг, обращающихся на организованном рынке ценных бумаг, или залог иного имущества, оформленный в порядке, предусмотренном статьей 73 настоящего Кодекса;\n\n3) поручительство третьего лица, оформленное в порядке, предусмотренном статьей 74 настоящего Кодекса.\n\nРешение о принятии обеспечительных мер отменяется также по заявлению налогоплательщика, в отношении имущества которого приняты указанные обеспечительные меры, в части, соответствующей объему исполненного решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения, либо в части, отмененной вышестоящим налоговым органом или судом.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случае направления копии решения по почте заказным письмом решение считается полученным по истечении шести дней с даты направления заказного письма. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\n14. Несоблюдение должностными лицами налоговых органов требований, установленных настоящим Кодексом, может являться основанием для отмены решения налогового органа вышестоящим налоговым органом или судом.\n\nНарушение существенных условий процедуры рассмотрения материалов налоговой проверки является основанием для отмены вышестоящим налоговым органом или судом решения налогового органа о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения. К таким существенным условиям относится обеспечение возможности лица, в отношении которого проводилась проверка, участвовать в процессе рассмотрения материалов налоговой проверки лично и (или) через своего представителя и обеспечение возможности налогоплательщика представить объяснения.\n\nОснованиями для отмены указанного решения налогового органа вышестоящим налоговым органом или судом могут являться иные нарушения процедуры рассмотрения материалов налоговой проверки, если только такие нарушения привели или могли привести к принятию руководителем (заместителем руководителя) налогового органа неправомерного решения.\n\n15. По выявленным налоговым органом нарушениям, за которые физические лица или должностные лица организаций подлежат привлечению к административной ответственности, уполномоченное должностное лицо налогового органа, проводившее проверку, составляет протокол об административном правонарушении в пределах своей компетенции. Рассмотрение дел об этих правонарушениях и применение административных наказаний в отношении физических лиц и должностных лиц организаций, виновных в их совершении, производятся в соответствии с законодательством об административных правонарушениях.\n\nПри этом течение сроков взыскания, предусмотренных настоящим Кодексом, приостанавливается на период приостановления исполнения решения о взыскании соответствующей задолженности. (В редакции  федеральных законов от 29.09.2019 № 325-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nВ случае, если по итогам рассмотрения материалов будет вынесено постановление об отказе в возбуждении уголовного дела или постановление о прекращении уголовного дела, а также если по соответствующему уголовному делу будет вынесен оправдательный приговор, руководитель (заместитель руководителя) налогового органа не позднее дня, следующего за днем получения уведомления об этих фактах от следственных органов, выносит решение о возобновлении исполнения принятых в отношении этого физического лица решения о привлечении к ответственности за совершение налогового правонарушения и решения о взыскании соответствующей задолженности.  (В редакции  федеральных законов от 28.12.2010 № 404-ФЗ, от 29.09.2019 № 325-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nВ случае, если действие (бездействие) налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) - физического лица, послужившее основанием для привлечения его к ответственности за совершение налогового правонарушения, стало основанием для вынесения обвинительного приговора в отношении данного физического лица, налоговый орган отменяет вынесенное решение в части привлечения налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) - физического лица к ответственности за совершение налогового правонарушения. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nСледственные органы, получившие от налоговых органов материалы в соответствии с пунктом 3 статьи 32 настоящего Кодекса, обязаны направлять в налоговые органы уведомления о результатах рассмотрения этих материалов не позднее дня, следующего за днем принятия соответствующего решения. (В редакции Федерального закона от 28.12.2010 № 404-ФЗ)\n\nКопии решений налогового органа, указанных в настоящем пункте, в течение пяти дней со дня вынесения соответствующего решения передаются (направляются) налоговым органом лицу, в отношении которого вынесено соответствующее решение (его представителю). (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.12.2009 № 383-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 101. Вынесение решения по результатам рассмотрения материалов налоговой проверки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"37eb80273c8c89ca6c8b85e2063b2aeeedf21c0eae901f15aa34a302ed99fc13"},{"code_id":"NK_RF","article_number":"101.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратила силу - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 101.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da905c5b8d842d66095408c41819a3a33c99abf499c463a1c920b89c47c7e307"}]$law7v021$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
